programs.sol:
"""A spelling-sensitive detector for have/has/having, when, and publicity words.

The largest responses are lexical: present-tense 'have' forms and 'when',
not verbs or question words generally. Chinese possession expressions and
'when + pronoun' starters are positive too. A secondary family concerns
celebrities, audiences, film/TV, and debuts. These rules assign typical
training-set strengths, not exact activations. Have contractions are weakly
positive; 'll/'d contractions are weakly negative. Document-initial 'When'
is stronger. Most other vocabulary and context variation are left at zero.
"""
READS = ()

POSSESSION = frozenset({'具有', '拥有', '擁有'})
CHINESE_PRONOUNS = frozenset({'我', '我们', '我們', '你', '你们', '你們',
                             '他', '他们', '他們', '她', '她们', '她們'})
CELEBRITY_WORDS = frozenset({'celebrity', 'celebrities', 'superstar',
                            'hollywood', 'backstage', '主演', '出演'})
PERFORMERS = frozenset({'actor', 'actress', 'singer', 'performer', 'rapper',
                        'broadcaster', '演员', '演員', '歌手', '模特'})
SCREEN_AND_RECORDINGS = frozenset({'film', 'films', 'movie', 'movies',
                                   'album', 'albums', 'television', 'tv',
                                   'studio', 'studios', 'cast'})
PREMIERES = frozenset({'debut', 'premiere', 'aired', 'airing'})
FIRST_APPEARANCES = frozenset({'debuted', 'premiered', 'starring'})
COMBAT_SPORTS = frozenset({'wrestle', 'wrestling', 'wrestler', 'wrestlers',
                          'ufc', 'wwe'})


def lexical_response(token, document_start):
    spelling = token.strip().lstrip('.-_')
    word = spelling.lower()
    spaced = token.startswith(' ')
    capital = bool(spelling) and spelling[0].isupper()
    if word == 'have':
        if not spaced and not capital and token == spelling:
            return 0.66
        return 0.85 if capital or token.startswith('.') else 0.75
    if word == 'has':
        return 0.62 if spaced and not capital else 0.29
    if word == 'having':
        return 0.70 if capital else 0.64
    if word == 'had':
        return -0.10 if capital else 0.08
    if word in {'haven', 'hasn'}:
        return 0.23
    if word in {"'ve", '’ve'}:
        return 0.18
    if word in {"'ll", '’ll', "'d", '’d'}:
        return -0.15
    if word == 'when':
        return 1.245 if document_start and token == 'When' else 0.79
    if word == 'whenever':
        return 0.46
    if spelling == '有':
        return 0.73
    if spelling in POSSESSION:
        return 0.55
    if spelling.endswith('有') and len(spelling) == 2:
        if spelling in {'没有', '沒有', '所有'}:
            return 0.0
        return 0.45
    if spelling.startswith('有') and len(spelling) <= 4:
        return 0.26
    if spelling in {'当', '當'}:
        return 0.60
    if spelling[:1] in {'当', '當'} and spelling[1:] in CHINESE_PRONOUNS:
        return 0.51
    if word in CELEBRITY_WORDS:
        return 0.66
    if word in PERFORMERS:
        return 0.44 if spaced or not word.isascii() else 0.13
    if word in {'fans', '粉丝', '粉絲'}:
        return 0.80
    if word == 'fan':
        return 0.24
    if word in {'viewers', 'critics', '观众', '觀眾'}:
        return 0.42
    if word in {'viewer', 'audience', 'audiences'}:
        return 0.20
    if word in SCREEN_AND_RECORDINGS:
        return 0.21
    if word in PREMIERES:
        return 0.38
    if word in FIRST_APPEARANCES:
        return 0.60
    if word in COMBAT_SPORTS:
        return 0.73
    if word in {'sports', 'sport', 'stadium', 'stadiums', 'arena'}:
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    return None, lexical_response(prefix.token_strings[-1], start)

programs.luna:
"""Approximate this sparse feature with a few common English cue words.
The component often responds strongly at forms of 'have' and at 'when';
most other tokens receive no contribution in this simple rule.
"""
READS = ()

# Typical positive sizes seen for these grammatical cue words.
CUE_SIZE = {
    "have": 0.77,
    "has": 0.65,
    "when": 0.79,
    "having": 0.68,
}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return None, float(CUE_SIZE.get(word, 0.0))

programs.haiku:
"""Layer-0 MLP down_proj component 3201: a "perform" detector.

It fires on the word "perform" and its forms, most strongly on "perform" and
"performing" (about 6-7 in the component's units), less on "performed" and
"performance"/"performer" (about 4-5), and on "of" right after "performance"
("the performance of ..."). More weakly it fires on words for carrying out or
producing something (transform, compute, implement, execute, complete, apply,
handle, conduct, behave) and their Chinese equivalents (执行 进行 实现 完成 表现
性能 行). Everything else predicts 0. Each prediction depends only on the current
token and the one before it.
"""

READS = ()

PERFORM_VERBS = {"perform", "performs", "performing", "perform."}
PERFORMED = {"performed", "performance", "performances", "performer", "performers"}
PERFORMANCE_ZH = {"性能", "表现", "表現", "绩效", "績效"}
ACTION_ZH = {"执行", "執行", "实现", "實現", "进行", "進行", "完成", "施行", "行", "开展", "做好"}
ACTION_VERBS = {
    "compute", "computed", "computing", "computation", "implement", "implemented",
    "implementing", "implementation", "execute", "executed", "execution", "apply",
    "applied", "applying", "conduct", "conducted", "conducting", "complete", "completed",
    "accomplish", "accomplished", "achieve", "achieving", "handle", "practice", "film",
    "behavior", "behave", "behaving", "behaviour",
}
WEAK_VERBS = {"do", "did", "done", "doing"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in PERFORM_VERBS:
        value = 6.5
    elif word in PERFORMED:
        value = 4.5
    elif word == "of" and before in PERFORMED:
        value = 2.5
    elif word.startswith("transform"):
        value = 1.5
    elif word in PERFORMANCE_ZH:
        value = 2.5
    elif word in ACTION_ZH:
        value = 1.5
    elif word in ACTION_VERBS:
        value = 1.0
    elif word in WEAK_VERBS:
        value = 0.5
    else:
        value = 0.0
    return None, value

programs.luna:
"""Guess activations for words about carrying out or finishing a task."""

READS = ()

ACTION_WORDS = {
    "apply", "permute", "implement", "practice", "handle", "execute",
    "film", "overcome", "conduct", "perform", "achieve", "complete",
    "demonstrate", "finish", "deform", "express", "exercise", "operate",
    "do", "work", "carry", "implementation", "operation",
}
CJK_ACTIONS = {"前行", "展现", "完成"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, tail = carry if carry is not None else (doc, "")
    if doc != old_doc:
        tail = ""

    piece = prefix.token_strings[-1]
    if piece[:1].isspace():
        tail = ""
    word = tail
    last_word = word
    for char in piece.strip():
        if char.isascii() and char.isalpha():
            word += char.lower()
        else:
            tail = ""
            if word:
                last_word = word
            word = ""
    if word:
        last_word = word

    stem = last_word
    for ending in ("ing", "ed", "es", "s"):
        if stem.endswith(ending) and len(stem) > len(ending) + 2:
            stem = stem[:-len(ending)]
            break
    has_ascii_word = any(char.isascii() and char.isalpha() for char in piece)
    value = 0.8 if ({stem, stem + "e"} & ACTION_WORDS) and has_ascii_word else 0.0
    if last_word == "performing" and has_ascii_word:
        value = 2.0
    if any(term in piece for term in CJK_ACTIONS):
        value = 0.7
    return (doc, word), float(value)

programs.sol:
"""A detector of medium-length indentation and separator runs.

Whitespace chunks of 7--23 spaces or 2--5 tabs activate strongly, with
peaks around 12--19 spaces and 3--4 tabs. Very long runs are weak or
negative. Runs one space short of a multiple of four get an extra boost.
Space indentation after a newline, and indentation early in a document,
are stronger. Whitespace ending a line and repeated separator marks have
smaller, separately calibrated responses. A single blank after an English
month name gets a small date-spacing response. An initial run of standalone
carriage returns also activates. Other text predicts zero.
"""

from math import exp

READS = ()

MONTHS = frozenset((
    "January February March April May June July August September October "
    "November December Jan Feb Mar Apr Jun Jul Aug Sep Oct Nov Dec"
).split())

# Response curves are indexed by character counts, never token identities.
SPACES = (
    (6, 0.059), (8, 0.488), (12, 1.362), (16, 1.577),
    (19, 1.327), (22, 0.524), (26, -0.049), (32, -0.423),
    (48, -0.285), (64, -0.131), (128, -0.246),
)
TABS = (
    (0, 0.0), (1, -0.01), (2, 1.039), (3, 1.626),
    (4, 1.622), (5, 1.117), (6, 0.45), (7, 0.20), (8, 0.0),
)
TAB_SPACES = (
    (0, 0.0), (1, -0.33), (3, -0.13), (5, 0.0),
    (7, 0.655), (11, 1.231), (15, 1.193), (19, 0.77),
    (23, -0.067), (27, -0.517), (40, -0.4),
)
LINE_SPACES = (
    (0, 0.0), (2, 0.0), (3, -0.165), (5, -0.18),
    (7, -0.054), (8, 0.15), (12, 0.68), (16, 0.81),
    (19, 0.62), (23, 0.09), (29, -0.45), (40, -0.6),
)
LINE_TABS = (
    (0, 0.0), (1, -0.025), (2, 0.195), (3, 0.745),
    (4, 1.008), (5, 0.49), (6, 0.05), (7, -0.2),
)
SEPARATORS = (
    (4, -0.05), (8, 0.18), (12, 0.58), (16, 0.85),
    (24, 0.1), (32, -0.15), (64, -0.1),
)
DOTS = (
    (4, -0.06), (6, 0.15), (8, 0.57), (16, 1.17),
    (24, 0.88), (32, 0.29), (64, -0.05),
)
DASHES = (
    (4, -0.02), (6, 0.06), (8, 0.26), (12, 1.03),
    (16, 1.35), (20, 1.0), (28, 0.1), (32, -0.11), (64, -0.05),
)


def curve(n, points):
    """Interpolate a response curve, clamping outside its landmarks."""
    if n <= points[0][0]:
        return points[0][1]
    for (x, y), (xx, yy) in zip(points, points[1:]):
        if n <= xx:
            return y + (yy - y) * (n - x) / (xx - x)
    return points[-1][1]


def space_run(n):
    if n < 6:
        return (0.0, 0.009, -0.017, -0.01, -0.037, -0.007)[n]
    value = curve(n, SPACES)
    if n % 4 == 3:
        value += 0.162 if n <= 19 else 0.375
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != doc else carry[1] + 1
    after_newline = position > 0 and '\n' in prefix.token_strings[-2]
    only_carriage_returns = position == 0 or carry[2]
    s = prefix.token_strings[-1]
    value = 0.0
    if s.isspace():
        chunks = s.replace('\r', '\n').split('\n')
        spaces = max(part.count(' ') for part in chunks)
        tabs = max(part.count('\t') for part in chunks)
        nbsp = max(part.count('\xa0') for part in chunks)
        newline = '\n' in s or '\r' in s
        if nbsp:
            value = curve(spaces + nbsp, (
                (0, 0.0), (1, -0.023), (2, 0.077), (4, 0.10),
                (7, 0.736), (8, 1.222), (16, 0.9), (32, 0.0),
            ))
            if spaces:
                value = -0.11 if spaces + nbsp == 2 else 0.8 * value
        elif tabs and spaces:
            if tabs == 1 and s.startswith('\t'):
                value = curve(spaces, TAB_SPACES)
            else:
                value = 0.8 * space_run(4 * tabs + spaces)
            if newline:
                value = curve(spaces, LINE_SPACES) - 0.1
        elif tabs:
            value = curve(tabs, LINE_TABS if newline else TABS)
            if not newline and tabs >= 2:
                value += 0.22 * exp(-position / 32) + 0.025 * after_newline
        elif newline:
            value = curve(spaces, LINE_SPACES)
            if s == '\r':
                value = 0.662 if only_carriage_returns else 0.05
        else:
            value = space_run(spaces)
            if spaces >= 6:
                value += 0.197 * exp(-position / 32) + 0.121 * after_newline
            elif s == ' ' and position > 0:
                previous_word = prefix.token_strings[-2].strip()
                if previous_word in MONTHS:
                    value = 0.24 if len(previous_word) == 3 else 0.135
    else:
        body = s.strip()
        if len(body) >= 4 and len(set(body)) == 1 and body[0] in '-=._/#*':
            value = curve(len(body), DASHES if body[0] == '-' else SEPARATORS)
            if body[0] == '.':
                value = curve(len(body), DOTS)
            elif body[0] == '_':
                value *= 0.65
            if '\n' in s:
                value = 0.5 * value - 0.12
    return (doc, position, only_carriage_returns and s == '\r'), float(value)

programs.luna:
"""Recognize spacing and alignment markers by their visible shape.

Medium-length whitespace runs are the main triggers: the estimate grows with
indent width, then tapers for unusually long runs. Long equals-sign rules are
another, weaker layout marker. Other tokens are predicted as inactive.
"""

import math

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token and all(ch.isspace() for ch in token):
        width = sum(
            4 if ch == "\t" else 1
            for ch in token
            if ch not in "\r\n"
        )
        if width < 5:
            return None, 0.0
        rise = 1.8 / (1 + math.exp(-(width - 9) / 2))
        taper = math.exp(-max(0, width - 16) / 12)
        value = rise * taper
        if "\n" in token or "\r" in token:
            value *= 0.6
        return None, float(value)
    if len(token) >= 8 and set(token) == {"="}:
        return None, float(0.05 * len(token))
    return None, 0.0

programs.sol:
"""Approximate a first-token/onset signal, not a topic detector.
The document's first token gets a large, spelling-dependent pulse: ordinary
fragments are negative, whereas familiar sentence openings and heading/code
introducers are often positive. Whitespace and chat markers have their own
onset values. Later tokens get small surface/word-class estimates; most of
the component's fine-grained lexical variation is deliberately left out.
"""
READS = ()

FUNCTION_WORDS = frozenset('''
the a an of to in on at by for from with and or but so as if
is are was were be been being have has had do does did that this
these those it its he she they we you i their our my his her
not no all any some what which who when where why how than then
'''.split())
# Literal metadata, conversation and question labels.
LABELS = {'<|im_start|>': -0.470, 'Title': 1.511, 'Human': 0.954, 'Q': 0.025}
QUESTION_OPENERS = {'What': 0.81, 'How': 0.38}
OPENERS = frozenset('Why Which It In There Can Is Let Please'.split())
MILD_OPENERS = frozenset('We You If When From For Who Could Does Are'.split())
PROMPT_OPENERS = frozenset('''
Write Create Describe Given Find Use Show Using Hi Today One Question Our Your
'''.split())
INDEFINITES = frozenset('''
something anything everything nothing someone anyone everyone somebody
anybody everybody thing things stuff
'''.split())
EVIDENTIAL_EMPHATIC = frozenset('''
actually really probably seems apparently certainly obviously clearly literally
'''.split())


def han(s):
    return bool(s) and all('\u4e00' <= c <= '\u9fff' for c in s)


def opening(s):
    w = s.strip()
    if s in LABELS:
        return LABELS[s]
    if s in QUESTION_OPENERS:
        return QUESTION_OPENERS[s]
    if s in {'The', 'This'}:
        return 0.37
    if s in {'A', 'An'}:
        return 0.25
    if s in OPENERS:
        return 0.23
    if s in MILD_OPENERS:
        return 0.12
    if s == 'I':
        return -0.045
    if s in PROMPT_OPENERS or (s.istitle() and s.lower() in FUNCTION_WORDS):
        return 0.0
    if s.startswith('#!'):
        return -0.05
    if s and set(s) == {'#'}:
        return 0.40 if len(s) <= 3 else 0.12
    if s.startswith('#'):
        return 0.24 if s == '#include' else 0.08
    if s in {'<?', '<!'} or s.startswith('//'):
        return 0.24 if '\n' in s or s.startswith('<') else 0.09
    if s == '/*':
        return 0.09
    if s in {'package', 'import', 'from', 'using'}:
        return 0.237 if s == 'package' else -0.02 if s == 'import' else -0.16
    if s.isspace():
        return -0.11 if '\n' in s or not s.isascii() else -0.50
    if not w:
        return -0.20
    if w.isdecimal():
        return -0.30
    if s[0].isspace():
        if s == ' The':
            return -0.665
        if w.isascii() and w.isalpha():
            return (-0.08 if w in FUNCTION_WORDS else -0.18) if w.islower() else -0.31
        return -0.21
    if s.isascii() and s.isalpha():
        if len(s) == 1:
            return -0.32 if s.isupper() else -0.45
        return -0.24 if s[0].isupper() else -0.28
    if s.isascii():
        if '\n' in s:
            return -0.10 if s.count('\n') > 1 else -0.18
        return -0.49 if s in {'.', ',', '(', '-', '/', '"', '*', '\\', '>'} else -0.27
    return -0.15 if han(s) else -0.20


def background(s):
    w = s.strip()
    if s in {'<think>', '</think>'}:
        return 0.135
    if s == '<|im_end|>':
        return -0.035
    if s.startswith(' ') and (w in INDEFINITES or w in EVIDENTIAL_EMPHATIC):
        return 0.09
    if han(w):
        return 0.032
    if not w or w.isdecimal() or not any(c.isalpha() for c in w):
        return 0.0
    if s.startswith(' ') and w.islower() and w.endswith(('ing', 'ly')):
        return 0.023
    return 0.006


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    reset = carry is None or carry[0] != doc
    n = 0 if reset else carry[1] + 1
    chat = s == '<|im_start|>' if reset else carry[2]
    if n == 0:
        value = opening(s)
    elif chat and n == 1:
        value = -0.056
    elif chat and n == 2 and s.isspace() and '\n' in s:
        value = 0.20
    else:
        value = background(s)
        if n < 16 and s not in {'<think>', '</think>', '<|im_end|>'}:
            value -= 0.04 / n ** 1.1
    return (doc, n, chat), float(value)

programs.luna:
"""Predict negative responses to decision, policy, and planning vocabulary.

Policy and strategy tokens tend to have the largest negative activations;
other related terms get a smaller negative value. Unlisted tokens are zero.
"""
READS = ()

STRONG_WORDS = {
    "policy", "policies", "strategy", "strategies", "strategic",
    "strategically", "政策", "策",
}
OTHER_WORDS = {
    "decision", "decisions", "decide", "decides", "deciding",
    "political", "politics", "budget", "budgets", "budgeting",
    "planning", "plan", "plans", "planned", "campaign", "campaigns",
    "tactic", "tactics", "criterion", "criteria", "rule", "rules",
    "制度", "预算",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in STRONG_WORDS:
        return None, -3.3
    if token in OTHER_WORDS:
        return None, -0.9
    return None, 0.0

programs.sol:
"""Recognize large quantities, with secondary fullness/restriction cues.

The strongest response is to Chinese 万/萬 and Korean 만 ('ten thousand'),
even outside numerical uses. A preceding digit slightly changes its size;
Korean -지만 ('but') is much weaker. Other number words, population, and
'of' in these quantity phrases respond less. Secondary lexical responses
cover fullness, Japanese 'only', and Chinese disorder characters.
Unrecognized tokens return zero; this is not a full activation model.
"""
READS = ()

# Large-number words and the population noun, with weaker lexical responses.
QUANTITY_WORDS = {
    'hundred': 0.30, 'hundreds': 0.23, 'undred': 0.5,
    'thousand': 1.28, 'thousands': 1.25,
    'million': 0.93, 'millions': 1.32, 'millionen': 0.95,
    'millones': 0.50, 'milhões': 0.45,
    'billion': 0.71, 'billions': 1.0, 'trillion': 0.67,
    'illion': 0.67, 'млн': 0.76, 'тыс': 0.86, 'тысяч': 0.47,
    'population': 0.79, 'populations': 0.98,
    '百': 0.44, '千': 0.74, '천': 0.82, '억': 0.83,
    '亿': 1.53, '億': 0.97,
}
FULLNESS = {
    '满': 1.85, '滿': 1.80, '満': 3.20, 'full': 0.21,
    '满足': 0.73, '滿足': 0.80, '满了': 0.45,
    '不满': 1.05, '不滿': 1.05,
    '充满': 0.40, '充滿': 0.40, '圆满': 0.40, '圓滿': 0.40,
}
RESTRICTION = {
    'だけ': 1.85, 'だけで': 0.72, 'ばかり': 1.40,
    'のみ': 0.98, '限り': 0.79, 'さえ': 1.10, '지만': 0.80,
}
DISORDER = {'乱': 2.20, '亂': 1.90, '混乱': 0.68}
QUANTITY_OF = {
    'thousands': 0.75, 'millions': 0.84, 'billions': 0.78,
    'hundreds': 0.25, 'population': 0.42, 'populations': 0.48,
    'million': 0.17, 'billion': 0.13,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    same_document = (prefix.position > 0 and
                     prefix.document_ids[-2] == prefix.document_ids[-1])
    previous = prefix.token_strings[-2] if same_document else ''
    numeric = previous.strip().isdigit()

    # Japanese 満 is split into byte tokens: recognize its completing token.
    if '\ufffd' in token:
        completed = prefix.text_prefixes[-1][-1:]
        if completed == '満':
            word = completed

    if word == '万':
        value = 5.10 if numeric else 5.65
    elif word == '萬':
        value = 5.47 if numeric else 5.92
    elif word == '만':
        if token.startswith(' '):
            value = 8.30
        elif previous.endswith('지'):
            value = 1.28
        else:
            value = 6.47 if numeric else 6.60
    elif word in {'一万', '一萬'}:
        value = 4.93
    elif word in {'十万', '十萬', '万余', '萬余'}:
        value = 3.90
    elif word in {'多万', '多萬'}:
        value = 4.60
    elif word in {'万人', '萬人', '万多', '萬多'}:
        value = 3.40
    elif word.startswith(('千万不', '千万别', '千萬不', '千萬別')):
        value = 0.30  # Emphatic 'do not', rather than a numerical quantity.
    elif '亿' in word or '億' in word:
