    "million", "millions", "billion", "billions", "thousand", "thousands",
    "hundred", "亿", "千", "億",
    "millón", "millones", "milhão", "milhões", "milliard", "milliards",
    "Million", "Millionen", "백만", "천",
}
POPULATION = {"population", "populations"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    before = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if word in TEN_THOUSAND:
        value = 5.8
    elif word in SCALE_WORDS:
        value = 1.0
    elif word in POPULATION:
        value = 0.8
    elif any(ch in word for ch in "万萬") and len(word) > 1:
        value = 2.5          # compounds: 十万, 千万, 万元, 百万, 万人
    elif word == "of" and before in SCALE_WORDS:
        value = 1.0          # "millions of", "thousands of"
    else:
        value = 0.0
    return carry, value

