    "laid", "found", "made", "thrown", "seen", "said", "known", "done",
    "gone", "given", "taken", "written", "built", "sent", "left", "kept",
    "held", "felt", "brought", "bought", "taught", "chosen", "shown",
    "broken", "spoken", "stolen", "worn", "born", "drawn", "driven",
    "eaten", "fallen", "grown", "risen", "caught", "paid", "sold", "told",
    "won", "stood", "understood", "forgotten",
}
SUBJECTS = {"i", "you", "we", "they", "he", "she", "it", "this", "that"}
ADVERBS = {"not", "just", "also", "still", "already", "never", "only", "then"}


def _participle(token):
    word = token.strip().casefold().rstrip(",.;:!?)]}")
    return len(word) >= 4 and (word.endswith("ed") or word in IRREGULAR)


def _be_before(history):
    words = [piece.strip().casefold() for piece in history]
    words = [word for word in words if word]
    for distance, word in enumerate(reversed(words[-4:])):
        if word in BE:
            between = list(reversed(words[-distance:])) if distance else []
            if distance == 0:
                return True
            if distance <= 2 and all(
                item.endswith("ly") or item in ADVERBS or item in {"re", "-", "-s", "\\"}
                for item in between
            ):
                return True
    if len(words) >= 2 and words[-1] in {"'re", "’re"}:
        return words[-2] in SUBJECTS
    return False


