    doc = prefix.document_ids[-1]
    old_doc, history = carry if carry is not None else (doc, ())
    if doc != old_doc:
        history = ()
    token = prefix.token_strings[-1]
    if _participle(token):
        value = -0.85 if _be_before(history) else -0.20
    else:
        value = 0.0
    return (doc, (history + (token,))[-4:]), value

