"""Layer 0 MLP down_proj component 3210 (negative on scope/ownership phrases).

What it does: this component goes negative on the word right after an adjective of
ownership or territory: "private", "personal", "local", "internal", "national", "community"
(and more weakly "world", "international", "home", "urban", ...). The size of the dip depends
on the word that follows: a generic noun gives a small dip, while a word that completes a
fixed phrase ("private static", "private practice", "internal bleeding", "personal trainer",
"community service", "/usr/local/bin") gives a large one. Predicting these dips, with the
values fitted to the component's activations, is the whole program. It reads only the two
newest tokens, so it needs no carry.
"""
READS = ()
# Ownership and territory adjectives ("private sector", "local government", "national team").
STRONG = {"private", "personal", "local", "internal", "national", "regional", "domestic", "corporate", "community"}
WEAK = {"world", "international", "urban", "interior", "home", "global", "inner", "central", "family", "neighborhood", "industry"}
# Words that often complete a fixed phrase after such an adjective ("private static", "internal bleeding").
HEADS = {"static", "final", "practice", "sector", "trainers", "trainer", "bleeding", "service", "services", "server", "war", "cup", "development", "standards", "office", "finance", "angle"}
# Function words, which do not complete a phrase.
FUNCTION = {"to", "in", "by", "was", "is", "and", "or", "of", "for", "with", "on", "at", "the", "a", "an", "that", "which", "who", "from", "as", "be", "can", "into", "its", "it", "their", "his", "her", "are", "were", "has", "have", "not", "s", "class", "int", "string"}

def _word(s):
    return s.strip(" \t\n/.-_").lower()

def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    cur = prefix.token_strings[-1].strip()
    cl = cur.lower()
    prev = _word(prefix.token_strings[-2])
    value = 0.0
    if prev in STRONG:
        value -= 0.19
        if cl in HEADS:
            value -= 1.84
        elif cur.isalpha() and cl not in FUNCTION:
            value -= 0.37
    elif prev in WEAK:
        value -= 0.04
        if cl in HEADS:
            value -= 0.98
        elif cur.isalpha() and cl not in FUNCTION:
            value -= 0.30
    if prev == "private" and cl in ("static", "final"):
        value -= 0.79
    if prev == "static" and cl == "final":
        value -= 1.5
    if prev == "local" and cur.startswith("/"):
        value -= 1.7
    return None, float(value)

