"""A detector for non-breaking spaces and bundled tab indentation.

A lone non-breaking space after text is positive, less so after a digit,
and largely suppressed after an ordinary space. A repeated one is weaker.
Tokens ending in multiple tabs have a large positive response; indentation
immediately after a newline is weaker than tabs after text or line numbers.
Tabs bundled with trailing whitespace have only a small response. Form feeds
and bare carriage returns are weakly negative. Other text is approximated
by zero; its smaller lexical responses are not modeled.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    last = previous[-1:]
    value = 0.0

    if token == '\f':
        value = -0.11
    elif token == '\r':
        value = -0.055
    elif token == '\xa0':
        if not previous:
            value = 0.25
        elif last == ' ':
            value = 0.02
        elif last == '\xa0':
            value = 0.20 if previous == '\xa0' else 0.08
        elif last == '\n':
            value = 0.40
        elif last.isdigit():
            value = 0.38
        else:
            value = 0.50
    elif token == ' \xa0':
        value = -0.10 if last == '\xa0' else 0.14
    elif token.isspace() and '\t' in token:
        tabs = token.count('\t')
        if '\n' in token or '\r' in token:
            value = 0.20 if tabs >= 2 else 0.02
        elif token.endswith(' '):
            value = 0.05 * min(tabs, 4) if tabs >= 2 else 0.0
        elif token == '\t':
            value = -0.05 if last == '\t' else 0.035
            if last == ' ':
                value = -0.11
        elif token.strip('\t') == '':
            value = 0.56 + 0.05 * min(tabs, 5)
            if last != '\n':
                value += 0.14
        elif token.startswith(' ') and token.lstrip(' ').strip('\t') == '':
            if tabs == 1:
                value = 0.57 if token.count(' ') == 1 else 0.45
            else:
                value = 1.0
        else:
            value = 0.45 + 0.08 * min(tabs - 1, 3)

    return (doc, token), float(value)

