"""Approximate rare activation spikes after common Romance function words.

In sampled training text, the component's activation was unusually positive on
the token after words such as ``que`` and ``se``, often in Spanish or Portuguese
clauses. Elsewhere its average is close to zero. The word list is a surface cue,
not a full grammar or a claim about every such occurrence.
"""

READS = ()
ROMANCE_FUNCTION_WORDS = frozenset({
    "que", "se", "si", "como", "cuando", "porque", "aunque", "para",
})


def step(carry, prefix, upstream):
    if len(prefix) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2]
        if previous.startswith(" ") and previous.strip().lower() in ROMANCE_FUNCTION_WORDS:
