"""Detect file names/locations and media resources, especially in code.

The main signal is lexical: files, paths, URLs, images, downloads, and file APIs.
Code notation changes the strength. Nearby related terms amplify combinations
such as PDF file, file path, and img src. A decaying count of filesystem words
supplies a modest topic boost; file/image responses also have a start-of-document
boost. All state resets at document boundaries. Unrecognized vocabulary is zero.
"""
import re

READS = ()
CAMEL_WORDS = re.compile('[A-Z]+(?=[A-Z][a-z]|$)|[A-Z]?[a-z]+')

# Familiar semantic classes, with approximate activation strengths.
CLASSES = {
    'file': (1.25, 'file files файл файлов fichier fichiers arquivo quivo '
                  'archivo archivos 文件 檔案 ファイル'),
    'filename': (2.05, 'filename filenames'),
    'stream_api': (1.9, 'InputStream OutputStream FileReader FileWriter'),
    'filepath': (2.65, 'filepath filepaths filesystem'),
    'temporary_file': (3.3, 'tempfile TemporaryFile NamedTemporaryFile'),
    'file_stream': (3.6, 'FileStream FileInputStream FileOutputStream'),
    'file_api': (2.35, 'readFile readFileSync writeFile writeFileSync '
                      'getFile getFiles openFile listFiles isfile fopen zipfile'),
    'path': (0.6, 'path paths 路径 路徑'),
    'path_api': (1.9, 'pathlib dirname basename splitext listdir mkdir '
                      'makedirs chdir getcwd unlink shutil abspath realpath'),
    'directory': (0.95, 'directory directories folder folders'),
    'dir': (0.65, 'dir dirs'),
    'image': (0.65, 'image images img ImageView getImage 图片 圖片 图像 画像'),
    'photo': (0.8, 'photo photos picture pictures photograph photographs '
                   'photography фото фот фотограф 照片 写真 相片 拍照'),
    'storage': (0.45, 'disk disks storage'),
    'video': (0.3, 'video videos movie movies 视频 視頻 影片'),
    'audio': (0.7, 'audio'),
    'transfer': (1.15, 'download downloads downloading downloaded upload '
                      'uploads uploading uploaded 下载 下載 上传 上傳'),
    'attachment': (1.5, 'attachment attachments'),
    'asset': (0.7, 'asset assets'),
    'url': (0.85, 'url urls uri uris BaseUrl urllib urlparse urlopen'),
    'source': (0.7, 'src href'),
    'resource': (0.65, 'resource resources 资源 資源'),
    'stream': (0.55, 'stream streams'),
    'loader': (0.45, 'load loads loader loaders loading save'),
    'image_format': (1.25, 'png jpg jpeg gif bmp tiff webp svg'),
    'format': (0.7, 'pdf txt csv xls xlsx docx mp3 mp4 wav'),
    'link': (0.35, 'link links hyperlink hyperlinks'),
    'figure_api': (2.8, 'savefig'),
    'url_scheme': (0.3, 'http https'),
    'temporary': (0.6, 'tmp temp'),
    'os': (0.4, 'os fs io'),
    'name': (0.0, 'name names'),
}
WORDS = {word.lower(): kind for kind, (_, words) in CLASSES.items()
         for word in words.split()}
FILES = {'file', 'filename', 'filepath', 'temporary_file', 'file_stream',
         'file_api', 'attachment'}
PATHS = {'path', 'directory', 'dir', 'path_api'}
IMAGES = {'image', 'photo', 'asset'}

def classify(token):
    word = token.strip().strip('._/([<,:=-\\\"\'')
    word = word.rstrip(')>]};:\"\'')
    kind = WORDS.get(word.lower())
    lower = [part.lower() for part in CAMEL_WORDS.findall(word)]
    if kind is None:
        # CamelCase file API names, not incidental substrings such as 'profile'.
        if 'file' in lower or 'files' in lower:
            kind = 'filename' if 'name' in lower else 'file_api'
        elif lower and lower[-1] == 'name' and 'image' in lower:
            kind = 'filename'
        elif lower and lower[-1] in {'path', 'image', 'url', 'uri'}:
            kind = WORDS[lower[-1]]
    if kind in {'os', 'url'} and word in {'os', 'io', 'uri'}:
        if token == word:
            kind = None  # Bare lowercase fragments are often word endings.
    image_qualified = 'image' in lower[:-1]
    return kind, word, image_qualified

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, history, position = None, 0.0, 0
    else:
        _, previous, history, position = carry
    token = prefix.token_strings[-1]
    core = token.strip()
    kind, word, image_qualified = classify(token)
    dotted = core.startswith('.')
    value = 0.0
    # Treat imageUrl like the two-token combination 'image URL'.
    if image_qualified and kind in {'path', 'url', 'name'}:
        previous = 'image'
    if kind:
        value = CLASSES[kind][0]
        if dotted and kind != 'format':
            value += 0.8 if kind in {'file', 'image', 'source'} else 0.3
        elif core.startswith('_'):
            value += 0.35
        elif core.startswith('/') and kind == 'source':
            value -= 0.4
        elif core.startswith(('(', '[', '<')):
            value += 0.15
        if word[:1].isupper() and kind in {'file', 'stream', 'path',
                                               'dir', 'resource'}:
            value += 0.45
        if not token[:1].isspace():
            if kind == 'file' and word.islower():
                value -= 0.15
            elif kind == 'asset' and word.lower() == 'assets':
                value += 1.5
        if kind == 'file':
            if word.lower() == 'files':
                value -= 0.15
            if previous in FILES | IMAGES | {'format', 'image_format', 'transfer'}:
                value += 1.8
            value += 0.2 * min(history, 4.0) + 4.0 / (position + 1)
        elif kind in {'path', 'name'} and previous in FILES:
            value += 1.5
        elif kind == 'path_api' and previous in PATHS:
            value += 0.9
        elif kind == 'source' and previous in IMAGES:
            value += 3.0
        elif kind == 'url' and previous in IMAGES | FILES | {'transfer'}:
            value += 1.8
        elif kind == 'image':
            value += 0.25 * min(history, 4.0) + 2.7 / (position + 1)
            if previous == 'loader':
                value += 1.3
        if kind == 'path':
            if word.lower() == 'paths':
                value -= 0.2
            value += 0.2 * min(history, 4.0)
            if previous == 'os':
                value += 1.0
        if kind in {'image', 'photo'} and any(ord(c) > 127 for c in word):
            value += 0.35
        if kind == 'name' and previous not in FILES:
            value = 0.0
    elif core == ':///':
        value = 2.1
    elif dotted and word.lower() in {'join', 'exists', 'resolve', 'open'}:
        value = 1.0 + (1.1 if previous in PATHS | FILES else 0.0)
    history = 0.96 * history + float(kind in FILES | PATHS)
    return (doc, kind, history, position + 1), float(value)

