    "png", "jpg", "jpeg", "gif", "mp3", "mp4", "zip", "slf",
}
CODE_WORDS = {"splitext", "loader", "loaders"}
MANDARIN_MEDIA = {
    "影音", "高清", "视频", "影片", "电影", "观看", "播放", "直播",
    "在线", "全集", "动漫", "图片", "下载", "资源",
}


def step(carry, prefix, upstream):
    words = set(re.findall(r"[\w]+", prefix.token_strings[-1].casefold()))
    if words & FILE_WORDS:
        value = 0.9
