"""Mark 'with', especially in familiar compound and participle phrases.

High-importance examples include 'along with', 'together with', and
participles such as 'associated with' and 'correlated with'.
"""

READS = ()

COMBINATION_WORDS = {"along", "together", "combined"}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token != "with":
        return None, 0.0
    previous = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if previous in COMBINATION_WORDS:
        return None, -1.0
    if previous.endswith("ed"):
