"""Approximate document-start pulses and weaker lexical/formatting responses.

Most first tokens get a negative pulse; newlines and periods are exceptions.
Its size depends on case, script, digits, whitespace, headings and markers.
Later tokens have a fading inverse-square-root tail. Selected intensifiers
and quantity words add positive offsets; a few protocol and math/formatting
marks have separate offsets. Individual-word quirks and most contextual
variation are deliberately left unmodeled.
"""
READS = ()

# Common degree modifiers and indefinite quantities tend to be positive.
INTENSIFIERS = {'very', 'quite', 'rather', 'too', 'pretty'}
QUANTITIES = {
    'some', 'several', 'many', 'much', 'more', 'most', 'few',
    'both', 'either', 'neither', 'each',
}
# Literal protocol delimiters and familiar mathematical/formatting marks.
MARKS = {
    '<tool_call>': -0.21,
    '<tool_response>': -0.08,
    '</tool_response>': 0.055,
    '··': -0.21,
    '$': 0.06,
    '$$': 0.10,
    '%': 0.04,
    '²': 0.045,
    '**': 0.06,
}


def ordinary_token(s):
    if s in MARKS:
        return MARKS[s]
    if s.startswith(' '):
        word = s.strip().lower()
        if word in INTENSIFIERS:
            return 0.10
        if word in QUANTITIES:
            return 0.045
    return 0.0


def start_pulse(s):
    word = s.strip()
    if s.startswith('<|'):
        return -0.38
    if not word:
        if '\n' in s:
            return 0.12 if s.startswith('\n') else 0.0
        return -0.24 + 0.035 * min(len(s), 4)
    if word.startswith('#'):
        return -0.52
    if word.startswith('.') and not any(c.isalnum() for c in word):
        return 0.075 if '\n' in s else 0.01
    if word.isdecimal():
        return -0.13
    if s in {'import', 'package'}:
        return -0.47
    if word.isascii() and word.isalpha():
        if s[0].isspace():
            return -0.17 if word.isupper() else -0.23
        if word.isupper():
            return -0.31
        return -0.35 if word.istitle() else -0.18
    if any('\u4e00' <= c <= '\u9fff' for c in word):
        return -0.29
    if word.isalpha():
        return -0.22
    return -0.19


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    n = 0 if carry is None or carry[0] != doc else carry[1] + 1
    if n == 0:
        value = start_pulse(prefix.token_strings[-1])
    else:
        value = 0.002 - 0.040 / n ** 0.5
        value += ordinary_token(prefix.token_strings[-1])
    return (doc, n), float(value)

