programs.haiku:
"""layers.0.mlp.down_proj:3226, as a word-level program.

The component is a small "facing hardship" feature read off the current token and the one
before it. It is largest on the verb "face" and its forms, which mean "to meet or confront"
(a challenge, a risk, a problem), and on related struggle words ("struggle", "suffer",
"navigate", "adverse"). It is also positive on "time" after "hard"/"harder" (have a hard
time), and on "of"/"from" after "free" (free of problems). It is negative on "of" after
"title" (title of), and it has one large negative spike on the ":" of a "Title:" line that
starts a document. Everywhere else it predicts 0."""

READS = ()

FACE_FORMS = {" face": 0.4, " faces": 0.3, " faced": 0.6, " facing": 0.4}
HARDSHIP = {" struggle": 0.2, " struggles": 0.2, " struggling": 0.3, " suffer": 0.2,
            " navigate": 0.25, " navigating": 0.25, " adverse": 0.2}
HARD_TIME = {" hard", " harder"}
FREE_BEFORE = {" free", " freedom"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    prev2 = prefix.token_strings[-3] if len(prefix.token_strings) > 2 else ""
    if tok in FACE_FORMS:
        return None, FACE_FORMS[tok]
    if tok in HARDSHIP:
        return None, HARDSHIP[tok]
    if tok == " time" and prev in HARD_TIME:
        return None, 0.8
    if tok in (" of", " from") and prev in FREE_BEFORE:
        return None, 0.6
    if tok == " of" and prev == " title":
        return None, -0.6
    if tok == ":" and prev == "Title" and prev2 == "<|endoftext|>":
        return None, -2.0
    return None, 0.0

programs.luna:
"""Predict a sparse set of face, time, and familiar collocation activations."""
READS = ()

FACE_FORMS = {"face", "faces", "faced", "facing"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()

    if word in FACE_FORMS:
        return None, 0.35
    if previous == "free" and word in {"of", "from"}:
        return None, 0.56 if word == "of" else 0.46
    if word == "of" and previous == "title":
        return None, -0.69
    if word == "practices" and previous == "best":
        return None, 0.48
    if word == "-time" and previous == "real":
        return None, 0.31
    if word == "time":
        if previous in {"hard", "harder"}:
            return None, 0.82
        if previous == "free":
            return None, 0.60
        if previous == "long":
            return None, 0.38
        if previous == "first":
            return None, 0.19
        if previous == "good":
            return None, 0.43
    if word == "like" and previous == "would":
        return None, 0.22
    if word == "on" and previous == "hard":
        return None, 0.57
    return None, 0.0

programs.sol:
"""A spelling-based approximation, not a single semantic detector.

The strongest contrast is among Indic phonetic letters: dental t/d and some
aspirated or sibilant consonants are negative; retroflex t/d are positive.
Unicode letter names carry that contrast across alphabets, with script-specific
corrections. Dependent vowel/nasal signs and several Thai syllable transitions
also matter. Incomplete UTF-8 is distinguished from completed characters.

Smaller rules cover Persian verb-ending spellings, a few katakana spellings,
English grammatical endings, SQL, chat markers, and fixed lexical constructions.
Only the previous token and latest completed character are carried, resetting
at document boundaries. Arbitrary content-word-specific variation is omitted.
"""
import unicodedata

READS = ()

# Unicode names use these same transliterations in the Indic alphabets.
INDIC_LETTERS = {
    'TA': -1.08, 'DHA': -0.85, 'SSA': -1.15, 'CHA': -1.05,
    'TTA': 0.90, 'DDA': 0.82, 'KHA': -0.60, 'NNA': -0.50,
    'DA': -0.57, 'PHA': 0.62, 'SA': 0.43, 'JA': 0.38,
    'YA': -0.20, 'VA': -0.22, 'RA': 0.10, 'LA': 0.22,
    'BHA': -0.17, 'CA': -0.18, 'MA': 0.09, 'NA': 0.17,
    'GHA': -0.30, 'TTHA': -0.43, 'JHA': 0.27, 'RHA': 0.30,
}
DEVANAGARI_MARKS = {
    'ा': -0.27, 'ि': -0.73, 'ी': -0.07, 'ु': -0.43,
    'ू': -0.15, 'े': -0.14, 'ो': -0.26, 'ं': -0.26,
    '्': -0.30, '।': -0.34,
}
GURMUKHI_MARKS = {'ਾ': -0.30, 'ਿ': 0.12, 'ੰ': -0.50}

THAI_LETTERS = {
    'ธ': -0.42, 'ษ': -0.39, 'ิ': -0.32, 'า': -0.26,
    'ื': -0.11, 'ึ': -0.14, 'ู': -0.13, 'ด': 0.31,
    'ซ': 0.27, 'น': 0.14, 'ล': 0.11, 'ช': 0.20,
    'ม': 0.14, 'ส': 0.12, 'บ': 0.07, '์': 0.29,
    'ข': -0.25, 'ถ': -0.26, 'ภ': -0.29, 'ย': -0.10,
    'ห': -0.12, 'ศ': -0.12, 'พ': -0.06, 'ั': 0.06,
    '้': -0.07, '่': -0.04, 'ี': -0.03, 'แ': 0.17,
}
THAI_VOWEL_SPELLINGS = {
    'ื่': -0.25, 'ี่': -0.10, 'ือ': -0.20, 'ีย': -0.20,
    'เบ': 0.49,
}
PERSIAN_VERB_ENDINGS = {
    'ند': -0.34, 'ود': -0.26, 'ید': -0.18,
    'ست': -0.19, 'است': -0.29,
}
ARABIC_LETTERS = {
    'ا': -0.10, 'د': -0.10, 'و': -0.07, 'ت': -0.08,
    'خ': -0.10, 'س': 0.14, 'ر': 0.10, 'ل': 0.09,
    'م': 0.07, 'ن': 0.07, 'ف': 0.09, 'ک': 0.08,
    'ی': 0.04, 'ژ': 0.37, 'ھ': -0.52, 'ع': -0.10,
    'ّ': -0.13, 'ْ': -0.17,
}

# These tokens are incomplete UTF-8 prefixes, not arbitrary lexical exceptions.
# E0 A5/A7/AB/A9 begin the upper half of Devanagari/Bengali/Gujarati/Gurmukhi.
INDIC_UPPER_HALF_PREFIX = {
    12619: -0.61, 26927: -0.40, 72219: -0.60, 65877: -0.24,
}


def orthography(text, fragment=False):
    s = text.strip()
    if not s:
        return None
    if s == 'ズ':  # Katakana zu.
        return 0.29
    if s == 'سس':  # A doubled Arabic sin (sibilant).
        return 0.73
    if s in PERSIAN_VERB_ENDINGS:
        return PERSIAN_VERB_ENDINGS[s]
    if s in THAI_VOWEL_SPELLINGS:
        return THAI_VOWEL_SPELLINGS[s]
    values = []
    for c in s:
        code = ord(c)
        if 0x0900 <= code <= 0x0D7F:
            name = unicodedata.name(c, '')
            if c in GURMUKHI_MARKS:
                value = GURMUKHI_MARKS[c]
            elif c in DEVANAGARI_MARKS:
                value = DEVANAGARI_MARKS[c]
                if fragment and c == 'ि':
                    value = -0.25
            elif 'LETTER ' in name:
                value = INDIC_LETTERS.get(name.split('LETTER ')[-1], 0.0)
            elif name == 'BENGALI VOWEL SIGN E':
                value = -0.55
            else:
                value = -0.10
            if 0x0B80 <= code <= 0x0BFF:
                value *= 0.45
            if name == 'GURMUKHI LETTER RA':
                value = 0.05
            elif name == 'GURMUKHI LETTER TA':
                value = -0.86
            elif name == 'GURMUKHI LETTER TTA':
                value = 1.10
            elif name == 'GURMUKHI LETTER DDA':
                value = 1.00
            elif name == 'TELUGU LETTER TA':
                value = -0.65
            values.append(value)
        elif 0x0E00 <= code <= 0x0E7F:
            values.append(THAI_LETTERS.get(c, 0.0))
        elif 0x0600 <= code <= 0x06FF:
            values.append(ARABIC_LETTERS.get(c, 0.0))
    if not values:
        return None
    value = sum(values) / len(values)
    if len(values) > 1 and any(0x0600 <= ord(c) <= 0x0E7F for c in s):
        value *= 0.25
    if text.startswith(' '):
        value = 0.4 * value - 0.025
    return value


QUANTIFIERS = frozenset('all each every any both some many more most much less '
                       'least few several various whole little'.split())
QUESTION_WORDS = frozenset('who whom whose what when where why whether how'.split())
NUMBER_WORDS = frozenset('one two three four five six seven eight nine ten '
                        'hundred thousand million billion'.split())
PUNCTUATION_RESPONSE = {
    '#': -0.015, '`': -0.012, '_': -0.004, '?': -0.006,
    '!': 0.017, ']': 0.010,
}


SUFFIX_RESPONSES = (
    (('tion', 'tions'), -0.009),
    (('sion', 'sions', 'ment', 'ments'), -0.022),
    (('ly',), 0.015),
    (('est',), 0.021),
    (('ing',), -0.006),
)


def ordinary(token, start, previous):
    """Small background responses to grammatical spellings and punctuation."""
    s = token.strip()
    word = s.lower()
    value = -0.0035 + (0.003 if token.startswith(' ') else 0.0)
    if start:
        value -= 0.010
    elif previous.strip().lower() in QUANTIFIERS:
        value -= 0.006
    if not s:
        if '\n' in token:
            value += 0.006 if token.count('\n') > 1 else -0.004
        if '\t' in token:
            value -= 0.009
    elif s.isascii() and s.isalpha():
        value -= 0.0007 * min(len(s), 12)
        for words, response in ((QUANTIFIERS, 0.028),
                                (QUESTION_WORDS, -0.010),
                                (NUMBER_WORDS, -0.013)):
            if word in words:
                value += response
        if len(word) > 3:
            for endings, response in SUFFIX_RESPONSES:
                if word.endswith(endings):
                    value += response
    elif s.isascii():
        if s.isdigit():
            value += 0.005
        for mark, response in PUNCTUATION_RESPONSE.items():
            if mark in s:
                value += response
        if s.startswith('/'):
            value -= 0.006
        if s in {'.', ',', ';'}:
            value += 0.005
    elif '\ufffd' in s:
        value -= 0.004
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    previous_char = '' if start else carry[2]
    latest_char = previous_char
    token = prefix.token_strings[-1]
    word = token.strip()
    value = ordinary(token, start, previous)
    if word == 'setq':  # Lisp's assignment special form.
        value = -0.49
    elif word == 'store':  # Shop/storage stem, including compounds.
        value = -0.11 if token.startswith(' ') else -0.29
    elif word == 'attention' and previous.strip().lower() == 'pay':
        value = -0.48
    elif token == '##' and start:
        value = -0.428
    elif token == ' TABLE':
        value = {'CREATE': -0.78, 'ALTER': -0.58, 'DROP': -0.37}.get(
            previous.strip(), -0.16)
    elif word == 'INTO' and previous.strip() == 'INSERT':
        value = -0.35
    elif token == '</tool_call>':
        value = -0.013 if start else 0.112
    elif token == '<think>':
        value = 0.096
    elif token == '</think>':
        value = 0.062
    else:
        fragment = '\ufffd' in token
        spelling = token
        if token.strip() == '\ufffd':
            # A continuation byte can finish a character that decoded badly alone.
            completed = prefix.text_prefixes[-1][-1:]
            spelling = completed if completed != '\ufffd' else token
        response = orthography(spelling, "\ufffd" in spelling)
        if spelling == 'ポ' and fragment and previous_char == 'ー':
            # An unmerged katakana po after the long-vowel mark.
            response = 0.65
        elif spelling == 'ਰ' and previous_char == 'ਤ':
            response = -0.52
        elif spelling == 'ि' and previous_char == 'त':
            response = -1.22
        elif spelling == 'ิ' and previous in {'ส', 'ธ'}:
            response = -0.68 if previous == 'ส' else -0.90
        elif spelling == 'ธ' and previous_char == 'เ':
            response = -0.80
        elif spelling == '์':
            if previous_char and previous_char in 'สซด':
                response = 0.70
            elif previous_char and previous_char in 'รล':
                response = 0.48
        elif spelling == 'ม' and previous_char == 'ั':
            response = 0.75
        if spelling and spelling[-1] != '\ufffd':
            latest_char = spelling[-1]
        elif spelling.rstrip('\ufffd'):
            latest_char = spelling.rstrip('\ufffd')[-1]
        if response is not None:
            value = response
        elif prefix.token_ids[-1] in INDIC_UPPER_HALF_PREFIX:
            value = INDIC_UPPER_HALF_PREFIX[prefix.token_ids[-1]]
    if '\ufffd' not in token:
        latest_char = token[-1:]
    return (doc, token, latest_char), float(value)

"""Predict the negative response to gaps that interrupt a continuing phrase.

The predictor remembers only the preceding token. Articles, conjunctions,
prepositions and auxiliaries have different calibrated responses from numbers
and sentence-ending punctuation. A class has calibrated responses to a space
and to a line break. Quotes, markup, math and escape introducers mix these
two responses.
Ordinary tokens get a near-zero baseline. This captures the separator behavior,
not all token-specific variation. Earlier context is deliberately ignored.
"""
READS = ()

# Grammatical words: (words, response to a space, response to a line break).
PHRASES = (
    ('and or but so then', -0.6, -1.15),
    ('the', -0.35, -1.15),
    ('a', 0.15, -0.45),
    ('an', -0.1, -0.65),
    ('of to by for than', -0.3, -1.1),
    # locations / ranges
    ('in on at from over under between within since until', -0.15, -0.95),
    ('with as into', -0.45, -1.05),
    ('is was', -0.2, -0.85),
    ('are were be been being', -0.3, -0.75),
    ('have has had', -0.45, -1.05),
    # clause introducers
    ('that which if whether because although where when while', -0.4, -0.95),
    # determiners
    ('this these those any each every some all such '
     'another other', -0.1, -0.65),
    # possessives
    ('my his her their our your its whose', -0.25, -0.95),
    ('it they he she we you', -0.1, -0.5),
    ('i', 0.05, -0.25),
    # auxiliaries / modifiers
    ('not do does did will would can could may might must should '
     'also only just', -0.05, -0.75),
    # prepositions
    ('about after before during without through like', 0.0, -0.75),
    ('using including', -0.35, -0.9),
)
WORD_RESPONSE = {
    w: (space, line)
    for words, space, line in PHRASES for w in words.split()
}
# Chat-format boundaries are also contexts for bare line breaks.
MARKERS = {
    '<tool_call>': (-0.25, -0.95),
    '<tool_response>': (-0.15, -0.6),
    '<think>': (-0.15, -0.65),
    '</think>': (0.0, -0.25),
    '<|im_end|>': (-0.05, -0.35),
}


def ending_response(token):
    word = token.strip()
    # Ignore bare lower-case fragments, which may be code identifiers.
    if word.lower() in WORD_RESPONSE and (
        token[:1].isspace() or word[:1].isupper()
    ):
        return WORD_RESPONSE[word.lower()]
    if word in MARKERS:
        return MARKERS[word]
    if not word:
        return (0.0, 0.05)
    if word.isdigit():
        return (0.0, 0.1)
    if word[-1] in ")]}」】》”’\"'":
        return (0.2, 0.25)
    if word[-1] in ".!?。！？":
        return (0.0, 0.0)
    if word[-1] in ",:;，、：；":
        return (0.0, -0.2)
    if word[-1] in "([{":
        return (-0.1, -0.45)
    if word.isalpha() and token[:1].isspace():
        return (0.0, -0.15)
    return (0.0, -0.05)


# (Offset, space-response multiplier, line-response multiplier).
GAPS = {
    'backslash': (-0.2, 0.1, 1.1),
    'bracket': (0.0, 0.15, 0.5),
    'crlf': (-0.15, -0.5, 1.1),
    'curlyquote': (-0.1, -0.05, 0.35),
    'escape_byte': (-0.05, 0.15, 0.7),
    'escn': (0.05, -0.4, 1.25),
    'indent': (0.0, 0.2, 0.05),
    'markup': (-0.05, 0.0, 0.6),
    'math': (-0.05, 0.45, 0.2),
    'nbsp': (-0.1, 0.0, 1.1),
    'newline': (0.0, 0.0, 1.0),
    'paragraph': (0.0, 0.05, 0.75),
    'quote': (0.0, 0.1, 0.25),
    'space': (0.0, 1.0, 0.0),
}


def gap_kind(token):
    word = token.strip()
    if token == " ":
        return "space"
    if token and token.isspace():
        if "\r\n" in token:
            return "crlf"
        if "\n" in token:
            return "paragraph" if token.count("\n") > 1 else "newline"
        return "nbsp" if "\xa0" in token else "indent"
    if token in ("\\", " \\"):
        return "backslash"
    if token == "\\n":
        return "escn"
    if word.startswith("\\x") and len(word) <= 4:
        if all(ch in "0123456789abcdefABCDEF" for ch in word[2:]):
            return "escape_byte"
    if word in ("“", "‘", "„", "«", "「", "『"):
        return "curlyquote"
    if token in (' "', " '"):
        return "quote"
    if token in (" ``", "``", " **", " *"):
        return "markup"
    if token.startswith(" ") and word and "$" in word:
        if set(word) <= set("$\\()"):
            return "math"
    if token in (" \\(", " \\["):
        return "math"
    if token in (" [", " <"):
        return "bracket"
    return None


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    token = prefix.token_strings[-1]
    previous = "" if carry is None or carry[0] != doc else carry[1]
    kind = gap_kind(token)
    value = -0.001
    if kind is not None:
        space, line = ending_response(previous)
        offset, a, b = GAPS[kind]
        value = offset + a * space + b * line
    return (doc, token), float(value)

programs.luna:
"""A small text-formatting response for line breaks and quote-like tokens.

These visible cues weakly identify positions where the component is negative;
most positions remain near zero, so the rule uses deliberately small values.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "\\" in token:
        value = -0.08
    elif "\n" in token or "\r" in token:
        value = -0.065
    elif token and token.isspace():
        value = -0.04
    elif any(mark in token for mark in ('"', "'", "“", "”", "「", "」")):
        value = -0.03
    else:
        value = 0.0
    return None, value

programs.sol:
"""A spelling-sensitive response to signs and signing.

' sign' and ' signs' are strongly negative; inflections, longer sign-words,
and split 'ign' spellings are weaker. A few Chinese/Russian sign words also
respond. 'Of' and 'up' retain a response immediately after a sign stem.
The end-of-text marker is positive. Unlisted text is predicted as zero;
in particular, whole 'design' and 'assign' tokens are not sign stems here.
"""

READS = ()

SIGN_FORMS = {
    'signed': -4.0,
    'signing': -5.0,
    'signer': -3.2,
    'signers': -3.2,
    'signings': -3.2,
    'signage': -3.2,
    'unsigned': -2.2,
    'signup': -1.6,
}
SIGN_FRAGMENTS = {
    'igned': -1.35,
    'igne': -1.1,
    'igner': -1.5,
    'esign': -1.3,
    'aign': -0.8,
    'ignant': -0.8,
    'sig': -0.65,
}


def word_part(token):
    return token.strip().lstrip('._-(/<').lower()


def response(token, word):
    if word in {'sign', 'signs'}:
        value = -6.6 if word == 'sign' else -6.8
        if token.startswith('Sign'):
            value = -8.1
        elif token.strip().startswith('Sign'):
            value = -7.1 if word == 'sign' else -7.8
        elif token.startswith('_'):
            value = -7.5
        return value
    if word == 'signed' and (not token[0].isspace() or 'Signed' in token):
        return -3.3
    if word in SIGN_FORMS:
        return SIGN_FORMS[word]
    if word == 'ign':
        if token.strip() == 'IGN':
            return -2.5
        if token.strip() == 'Ign':
            return -0.8
        return -1.45 if token[0].isspace() else -3.0
    if word in SIGN_FRAGMENTS:
        return SIGN_FRAGMENTS[word]
    if word == 'signific':
        return -2.2
    if word.startswith('significant') or word in {
        'signify', 'signifies', 'signaling', 'signalling'
    }:
        return -1.35
    if word.startswith(('signature', 'significance', 'insign')):
        return -1.0
    # Written equivalents: signing agreements, signatures, signs.
    if word in {'签署', '签订', '簽署', '簽訂'}:
        return -3.4
    if word in {'签', '签名', '签约', '簽', '簽名', '簽約'}:
        return -2.0
    if word in {'签字', '簽字', '迹象', '跡象'}:
        return -2.7
    if word in {'标志', '標誌', '徵', '征'}:
        return -1.4
    if word == 'знак':
        return -2.2 if token[0].isspace() else -1.3
    if word == 'подпис':
        return -1.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    prior = '' if carry is None or carry[0] != doc else carry[1]
    word, previous = word_part(token), word_part(prior)
    value = response(token, word)
    if token == '<|endoftext|>':
        value = 1.41
    elif previous in {'sign', 'signs', 'signing', 'signed'}:
        if word == 'of':
            value -= 2.65 if previous in {'sign', 'signs'} else 2.3
        elif word == 'up':
            value -= {'signed': 0.9, 'signing': 1.4}.get(previous, 1.8)
            value -= 0.65 * ('Sign' in prior) + 0.65 * ('Up' in token)
        elif value == 0.0 and token and not token[0].isspace():
            # Inflections can be split: Sign+s, -sign+ing, sign+er.
            if word == 's':
                value = -6.8 if 'Sign' in prior else -4.2
            elif word == 'ing':
                value = -5.0
            elif word in {'er', 'e'}:
                value = -2.1
            elif word == 'i':
                value = -1.5
            elif word.isalpha():
                value = -0.8
    elif previous == 'ign' and word in {'s', 'ing'} and not token[0].isspace():
        value -= 2.0
    return (doc, token), float(value)

programs.luna:
"""Predict sparse responses to end markers and sign-related spellings.

End-of-text gets a positive pulse; tokens spelling sign/signs/signed get
negative pulses, strongest for those exact forms. Other tokens containing
``sign`` or ``ign`` get a smaller negative pulse, as does ``of`` immediately
after ``sign``. Other tokens are predicted as zero.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().casefold()

    if token == "<|endoftext|>":
        return None, 1.45
