    (frozenset(('either', 'neither')), -0.12),
    (frozenset(('same', 'identical', 'alike', 'similar')), -0.055),
    (frozenset(('whole', 'all', 'both', 'entire')), -0.035),
    (frozenset(('something', 'anything')), 0.065),
    (frozenset(('remain', 'remains', 'stay', 'stays', 'staying')), 0.12),
    (frozenset(('work', 'labor', 'effort', 'energy')), -0.055),
