    'eslint': -0.25,       # JavaScript linter
    '.util': 0.22,         # utility namespace
    '/org': 0.17,          # organization path segment
    '.log': 0.09,          # logging method / file extension
    '_modules': -0.09,     # node_modules suffix
    '\\modules': 0.61,     # PHP namespace segment
}

