    if token == '<|im_start|>':
        # Early message starts are weaker than starts deep in a conversation.
        value = 0.176 if position == 0 else 0.30 - 0.06 / (1 + position / 25)
    elif token == '<|im_end|>':
        if previous == '</tool_response>':
            value = 0.089
        elif previous == '</tool_call>':
            value = 0.038
        elif previous.rstrip().endswith(('.', '?', '!', '。', '？', ':')):
            value = -0.080
        else:
