        elif word == 'bên':                 # side / beside
            value = 0.55
        elif word == 'ngày':                # day
            value = 0.46
        elif word == 'cuộc':                # event / activity classifier
            value = 0.43
        elif word == 'mình':                # self / oneself
            value = 0.27
        elif word == 'những':               # plural determiner
            value = -0.33
        elif word.endswith('NotFoundException'):
            # ClassNotFoundException can span two tokens.
            name = previous.strip() + word
            value = (-0.80 if name.endswith('ClassNotFoundException')
                     else -0.54)
        elif word == 'AssertionError':
            value = -0.59
        elif word == 'SQLException':
            value = -0.43
        elif word.endswith('Exception'):
            value = -0.12
        elif token.strip() in CODE_FORMS:
            value = CODE_FORMS[token.strip()]
        elif token.strip() in {'.js', '.go', '.py', '.ts', '.java', '.cpp',
                               '.html', '.css'}:
            value = 0.045
        elif token.strip() in {"'s", '’s'}:
            value = -0.039          # English possessive / contracted is
