import re

READS = ()
FIRST_SECOND_PERSON = {'i', 'we', 'you'}
THIRD_PERSON = {'he', 'she', 'it', 'they'}
ROMAN_D = re.compile(r'\\(?:mathrm|textrm)\s*\{?\s*$')


