    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    before = previous.strip().lower()
    value = 0.0

    if word.lower() == 'would':
        value = 0.79
        if before in FIRST_SECOND_PERSON:
            value = 1.12
        elif before in THIRD_PERSON:
            value = 0.95
        if word != 'would' or token == 'would':
            value = 0.65
    elif word.lower() == 'wouldn':
        value = 0.55
    elif word in {"'d", '’d'}:
        value = 1.1
        if before in FIRST_SECOND_PERSON:
            value = 1.92
        elif before in THIRD_PERSON:
            value = 1.68
    elif word == 'd':
        if token == 'd':
            value = 1.74
            if previous and previous[-1].isalpha():
                value = 1.18 if previous[-1].isascii() else 0.85
            elif previous.endswith('%'):
                value = 1.88
            elif previous.endswith('\\'):
                value = 2.4
            elif previous.endswith('\n'):
                value = 1.6
        elif token.startswith('\t'):
            value = 1.0
        else:
            value = 1.38
        if ROMAN_D.search(tail):
            value = 3.45 if tail.rstrip().endswith('{') else 2.8
    elif word.endswith('d') and all(not c.isalnum() for c in word[:-1]):
        punctuation = word[:-1]
        if punctuation in {'-', '_'}:
            value = 0.78
        elif punctuation == '/':
            value = 1.29
        else:
            value = 1.08
    elif word.endswith('D') and all(not c.isalnum() for c in word[:-1]):
        value = 0.2
    elif word == 'д':
        value = 0.3
    elif word == 'dd':
        value = 0.65
    elif word in {'mathrm', 'textrm'}:
        value = 0.5

    return (doc, token, (tail + token)[-64:]), float(value)

