programs.sol:
"""Prefix-to-stem word-piece boundaries.

Predict a negative pulse when a familiar derivational prefix is followed by a
consonant-led continuation, e.g. ex|haust, in|finite, or sub|duction. Short pieces
and space-prefixed beginnings are stronger. Vowel-led continuations are usually
positive; a camel-case capital weakens the pulse. Re followed by ':' is positive.
Short ASCII fragments with one vowel get a weak fallback outside the inventory.
The inventory matches prefix spellings; it does not verify actual morphology.
Only the preceding token is remembered; documents reset this memory.
"""
import unicodedata

READS = ()

# Familiar affixes, grouped by language family and approximate response size.
FAMILIES = (
    (1.10, 'от под об пред рас воз вос интер кон'),
    (0.64, 'раз из ис вы по при пре про пере за на до ком ин ос над без бес'),
    (0.64, 'де дез дис ре суб экс транс пост'),
    (0.41, 'с в у о з'),
    (0.90, 'ab con ex ob per inter trans circum out under'),
    (0.90, 'ent ver zer aus auf ein vor nach mit über unter kon kom'),
    (0.90, 'dé pré ré des'),
    (0.59, 'ad an be com de dis en im in pre pro re sub un over'),
    (0.39, 'em er ge es é sup post sur fore um om on'),
    (0.39, 'anti auto dys hyper hypo micro macro mono multi non poly syn sym'),
    (0.39, 'super supra contra od pod roz prze przy przed před pře při'),
)
STRENGTH = {
    p: weight for weight, words in FAMILIES for p in words.split()
}
GERMAN = set('ent ver zer aus auf ein vor nach mit über unter an ab zu'.split())
ARABIC = {'ت', 'م', 'ي', 'إ', 'است', 'إست'}
VOWELS = set('aeiouyаеёиоуыэюяіїєای')


def trailing_letters(s):
    i = len(s)
    while i and s[i - 1].isalpha():
        i -= 1
    return s[i:].lower()


def prefix_strength(p):
    if p in STRENGTH:
        return STRENGTH[p]
    if p.endswith('ge') and p[:-2] in GERMAN:
        return 0.9  # Separable German prefix plus participial ge-.
    for head in ('re', 'de', 'in', 'un', 'ac'):
        if p.startswith(head) and p[len(head):] in {'com', 'con'}:
            return 0.9  # Stacked Latin-derived prefixes.
    # Arabic derivational prefixes, optionally with article or conjunction.
    if p.startswith('و'):
        p = p[1:]
    if p in ARABIC:
        return 0.65
    if p.startswith('ال') and p[2:] in ARABIC:
        return 0.85
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    p = trailing_letters(previous)
    strength = prefix_strength(p)
    value = -0.002
    if p == 're' and s.startswith(':'):
        value = 1.2
    elif s[:1].lower() == 'ь':  # A soft sign is not a consonant sound.
        value = 0.0
    elif s[:1].isalpha():
        first = unicodedata.normalize('NFD', s[0].lower())[0]
        if s[0] in 'أإ':  # Hamza is a consonant, unlike plain alif.
            first = 'ء'
        if strength and first in VOWELS:
            vowel_friendly = p in {'re', 'de', 'com', 'con', 'sub'}
            value = 0.55 if vowel_friendly else 0.15
            if first in {'o', 'о'}:
                value *= 0.4
            if first in {'я', 'ю'}:
                value = -0.25
        elif strength:
            if len(s) > 3:
                strength *= 0.67 if len(s) <= 6 else 0.44
            if previous[:1].isspace():
                strength *= 1.52
            elif previous[:1].isupper():
                strength *= 1.25
            else:
                strength *= 0.9
            if first in 'rnрн':
                strength *= 0.45
            elif first in 'pfmпфм':
                strength *= 1.1
            if s[0].isupper():
                same_caps = s.isupper() and previous.strip().isupper()
                strength *= 0.9 if same_caps else 0.15
            value = -strength
        elif p and p.isascii() and first not in VOWELS and len(p) <= 3:
            vowels = sum(c in VOWELS for c in p)
            if vowels == 1 and (len(p) == 1 or p[-1] not in VOWELS):
                value = -0.1 if len(p) <= 2 else -0.06
                if previous[:1].isspace():
                    value *= 1.5
    return (doc, s), float(value)

"""A lexical approximation of protocol, grammatical, and spelling responses.

Give the largest response to a tool-call opening; smaller peaks mark message
and thought boundaries. Other peaks cover negative-contraction fragments,
uncertainty words, personal question words, zero, and structured syntax.
For remaining tokens, use length, capitalization, writing system, and English
endings. This captures recurring classes, not arbitrary word-specific effects.
The program uses only the current token, so it needs no document state.
