READS = ()

PROTOCOL = {
    '<tool_call>': 4.43,
    '<|im_end|>': 1.91,
    '<|im_start|>': 1.63,
    '<tool_response>': 1.63,
    '<think>': 1.69,
    '</think>': 1.69,
