# documentation comments, escapes, comparison, and carriage return.
SYNTAX = {
    '{"': 0.73, ',"': 0.52, ':"': 0.33,
    '->': 0.44, '=>': 0.44, ':=': 0.44,
    '_{': 0.51, '^{': 0.51, '[]': 0.55, '///': 0.44,
    '\\"': 0.34, '"\\': 0.34, '\\u': 0.40, '\\xc': 0.40,
    '<': -0.09, '\r': 0.49,
