don doesn didn isn aren wasn weren haven hasn hadn
wouldn couldn shouldn mustn needn
'''.split())
UNCERTAINTY = frozenset('''
maybe perhaps possible possibly seem seems apparently uncertain
'''.split())
POSITIVE_INTEGERS = frozenset('''
one two three four five six seven eight nine ten eleven twelve
'''.split())
FUNCTION_WORDS = frozenset('''
a an the and or but if when where whether that which what how as than
to of in on at by for from with into about through between without within
is am are was were be been being do does did have has had can could
will would shall should may might must not no it its this these those
he she they we you i me him her them us my your our their his
all some most more same such another
'''.split())
# Verb, noun, and adjective endings when emitted as separate word fragments.
ENDING_FRAGMENTS = {
    'ized': -0.37, 'izing': -0.37, 'ing': -0.14,
    'ity': 0.38, 'ial': 0.38, 'ical': 0.38,
    'ion': 0.21, 'ation': 0.21, 'ations': 0.21, 'ness': 0.21,
}
# Chinese characters, Japanese kana, Cyrillic, Arabic, Korean Hangul.
SCRIPT_CORRECTIONS = (
    (0x4E00, 0x9FFF, -0.137),
    (0x3040, 0x30FF, -0.051),
    (0x0400, 0x052F, 0.059),
    (0x0600, 0x06FF, -0.157),
    (0xAC00, 0xD7AF, -0.011),
)


def spelling_response(t):
    """Background response from case, length, script, and English endings."""
    if t.lower() in FUNCTION_WORDS or not t or t.isdigit():
        return 0.006
    if '\ufffd' in t:
        return 0.11
    if not any(c.isalpha() for c in t):
        return 0.017
    value = 0.05
    if len(t) > 6:
        value += 0.035
    if len(t) > 10:
        value += 0.075
    if len(t) == 1:
        value -= 0.077
    if not t.isalpha():
