        if len(t) > 3 and t.endswith('ed'):
            value -= 0.083
        if len(t) > 4 and t.endswith('ing'):
            value -= 0.104
        if len(t) > 3 and t.endswith('ly'):
            value -= 0.059
        if len(t) > 3 and t.endswith('s'):
            value -= 0.031
    return value


