    s = prefix.token_strings[-1]
    t = s if s == "\r" else s.strip()
    word = t.lower()
    if t in PROTOCOL:
        value = PROTOCOL[t]
    elif t.startswith('<') and t.endswith('>'):
        value = -0.02
    elif word in NEGATIVE_AUXILIARY_STEMS:
        value = 0.50
    elif word in UNCERTAINTY:
        value = 0.49
    elif word == 'who':
        value = 0.68
    elif word in ('whom', 'whose'):
        value = 0.28
    elif word == 'zero':
        value = 0.77
    elif word in POSITIVE_INTEGERS:
        value = -0.08
    elif t in SYNTAX:
        value = SYNTAX[t]
    elif not s.startswith(' ') and word in ENDING_FRAGMENTS:
        value = ENDING_FRAGMENTS[word]
    elif t in ("'ve", '’ve'):
        value = 0.57
    elif t in ("'ll", '’ll'):
        value = 0.37
    else:
        value = spelling_response(t)
    return None, value

