    'ent': 0.95, 'ant': 0.27, 'ern': 0.85,
    'ance': 0.54, 'ence': 1.10, 'ian': 0.44, 'ia': 0.35, 'io': 0.36,
    'ion': 0.36, 'ium': 0.27, 'ous': 0.26, 'ial': 0.24, 'ien': 0.47,
    'ic': 0.20, 'ен': 1.00, 'ан': 0.72,
