               'various', 'different'}


def score(text):
    s = text.lower()
    if not s:
        return 0.0
    if s[0].isspace():
        word = s.strip()
        if word in {'a', 'an'} or word in QUANTIFIERS:
            return -0.18
        if word in {'this', 'these'}:
            return 0.2
        return 0.0
