        value = 2.0 if c in I else (1.0 if c == 'ы' else 1.6)
        if d in 'bcgklpxбкглпх':
            value += 1.0
        if d in 'aeiouftdsmаеёиоуяюыфдтсм':
            value += 0.4
        if s in {'iv', 'ive', 'ives', 'ived', 'ivity', 'ив'}:
            value += 1.6 * math.sqrt(length)
        if c in 'yýjь' and d in 'nmнм':
            value += 1.2
        if s.startswith('iz') and len(s) > 2:
            return 0.5
        if len(s) > 4 or s.startswith(('ian', 'ician')):
            value -= 0.6
    elif c in A:
        value = -0.3
        if d in 'nmruvнмрв':
            value -= 1.0
        if d in 'cfltsкфлтс':
            value -= 0.4
        if s.startswith(('and', 'ant')):
            value += 0.7
        if s.startswith(('ans', 'anz', 'anc', 'arn', 'ander', 'ар')):
            value -= 1.0
    elif c in E:
        value = 0.6 if c == 'е' else 0.3
        if d in 'nrlzнрлз':
            value -= 0.6
        if d in 'gkгк':
            value += 1.0
        if d in 'ydspbйдспб':
            value += 0.3
    elif c in O or c in U:
        value = 1.0 if c in O else 1.3
        if d in 'cgkpbtdсгкпбтд' or (c in U and d in 'lsлс'):
            value += 0.6
        if len(s) > 4:
            value -= 0.3
