"""Approximate the component using spellings of 'name' and 'new'.

The strongest response is to 'name'; 'new' gives a smaller positive response.
Capitalization and whether punctuation joins the word change the amplitude.
Related words and translations get weaker responses. A few name phrases,
JSON keys and LaTeX command suffixes adjust the response; otherwise zero.
The only state is the preceding token, reset at document boundaries.
Small background responses and more detailed context effects are omitted.
"""
import re

READS: tuple[str, ...] = ()

# Common translations of 'name' and 'new', rather than arbitrary vocabulary IDs.
NAME_WORDS = {
    'nom': 0.42, 'nome': 1.05, 'nombre': 0.97, 'namen': 0.94,
    'название': 0.82, 'имени': 0.82, '이름': 1.7, '명': 0.9,
}
NEW_WORDS = {
    'neue': 0.72, 'neuen': 0.61, 'nouveau': 0.6, 'nuevo': 0.6,
    'mới': 0.53, 'нов': 0.39, '새': 0.75,
}


def lexical_value(token):
    stripped = token.strip()
    word = stripped.strip("._-/'\"()[]{}<>=,;:")
    lower = word.lower()
    space = token.startswith(' ')
    joined = word != stripped
    if lower == 'name':
        if joined:
            return 1.9 if stripped.startswith('_') else 2.0
        if word.isupper():
            return 2.45 if space else 2.31
        if word[0].isupper():
            return 2.14
        return 2.2 if space or token.startswith('\t') else 2.5
    if lower == 'names':
        return 1.9 if space else 1.6
    if lower == 'named':
        return 1.45 if space and word.islower() else 1.15
    if lower in {'naming', 'rename', 'renaming', 'renamed', 'unnamed'}:
        return 1.1
    if lower == 'namely':
        return 0.51
    if lower == 'new':
        if word.isupper():
            return 1.23
        if word[0].isupper():
            return 1.36 if joined else (1.62 if space else 1.55)
        return 1.29 if space else 1.13
    if lower == 'newly':
        return 0.61
    if lower in {'newer', 'newest', 'newborn', 'newfound'}:
        return 0.38
    if lower.startswith('renew'):
        return 0.47
    # Fragments of 'name' exposed by subword tokenization.
    if lower in {'nam', 'ames', 'amed'}:
        if lower == 'nam':
            return 0.75
        return 0.53 if lower == 'ames' else 0.3
    if lower in NAME_WORDS:
        return NAME_WORDS[lower]
    if lower in NEW_WORDS:
        return NEW_WORDS[lower]
    if word == '名':
        return 2.14 if not space else 1.65
    if word in {'名称', '名字', '姓名', '名为', '命名为'}:
        return 1.35
    if word in {'一名', '两名', '名叫', '有名'}:
        return 1.7
    if '名' in word:
        return 0.55
    if word == '新':
        return 1.11 if not space else 0.87
    if word == '的新':
        return 1.25
    if word == '新的':
        return 0.95
    news_prefixes = ('新闻', '新聞', '新华', '新浪')
    if word.startswith('新') and not word.startswith(news_prefixes):
        return 1.1 / len(word)
    if '新' in word:
        return 0.1
    # Common identifier compounds, such as userName or getName.
    if lower.endswith(('name', 'names')):
        if lower.startswith(('get', 'set', 'by', 'full')):
            return 1.25
        return 0.5
    if lower in {'namespace', 'namespaces'}:
        return 0.25
    if re.match(r'new[A-Z]', word):
