    document = prefix.document_ids[-1]
    previous = ''
    if carry is not None and carry[0] == document:
        previous = carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    before = previous.strip().lower()
    value = lexical_value(token)
    if word == 'name':
        # A JSON key, a LaTeX command suffix, or a modified noun phrase.
        if previous.rstrip().endswith('{"'):
            value = 2.72
        elif before.endswith('operator'):
            value = 0.9
        elif token.startswith(' '):
            if before == 'given':
                value = 2.61
            elif before in {'first', 'last', 'family'}:
                value = 1.73
            elif before in {'domain', 'param'}:
                value = 1.3
            elif before in {'function', 'variable', 'file', 'class', 'user'}:
                value = 1.85
    elif token == ' of' and before in {'name', 'names'}:
        value = 0.72
    elif token == ' new':
        if before in {'a', 'an', 'this', 'your', 'their'}:
            value = 1.2
        elif before == 'fn':
            value = 1.61
    return (document, token), float(value)

