"""Recognize line-comment punctuation, not comment contents.

Double slashes produce a large negative pulse, especially at document start.
The pulse weakens with token position. Empty comments, documentation markers,
URL separators, and indented hash comments have smaller responses. All other
text is predicted as zero. The position counter resets between documents.
"""
from math import sqrt

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    n = carry[1] if carry is not None and carry[0] == doc else 0
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if n else ''
    marker = token.strip()
    spaced = token.startswith(' ')
    newline = '\n' in token or '\r' in token
    value = 0.0

    if marker == '//':
        if newline:
            value = -1.0 if spaced else -1.1
        elif n == 0:
            value = -5.35 if spaced else -9.61
        elif n == 1 and previous.strip() == '//' and '\n' in previous:
            value = -7.79
        else:
            value = (-2.67 if spaced else -2.95) - 2.9 / sqrt(n + 1)
    elif marker.startswith('://'):
        value = -0.86 if marker == '://' else -0.4
    elif marker.startswith('///') and not marker.startswith('////'):
        value = -0.19 if newline else (-0.55 if spaced else -0.80)
    elif marker.startswith('//!'):
        value = 0.0 if newline else -0.58
    elif marker.startswith('//'):
        value = -0.65 if newline else (-2.0 if len(marker) <= 8 else -1.4)
    elif marker.endswith('//'):
        before = marker[:-2]
        if before.endswith(';'):
            value = -4.35 if before.endswith('();') else -3.55
        elif before.endswith(')'):
            value = -2.6
        elif before.endswith(('{', '}')):
            value = -2.8
        elif before.endswith(('"', "'")):
            value = -3.8
    elif marker == '#':
        if n == 0:
            value = -0.15
        elif previous.isspace() and '\n' not in previous:
            value = -0.42 if spaced else -0.21
        else:
            value = -0.05 if spaced or '\n' in previous else 0.12

    return (doc, n + 1), float(value)

