"""Layer-0 MLP down-projection component 3258: a "comment opener" detector.

It fires (negatively) on the token that opens a code comment. The strongest response
is to a double-slash line-comment opener `//` (also ` //`, ` "//`, `)//`), about -3 to -4.
URL separators `://` respond weakly (about -0.9), runs of slashes `///` about -0.6,
block-comment openers `/*` about -0.5, and hash comments ` #` about -0.4. Every other
token gives 0. The program needs no memory of earlier tokens.
"""

READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if "://" in tok:
        value = -0.9  # URL separator
    elif "///" in tok:
        value = -0.6  # slash run, e.g. a banner comment
    elif "//" in tok:
        value = -3.2  # line-comment opener
    elif tok.endswith("/*") or tok == "/*":
        value = -0.5  # block-comment opener
    elif tok.strip() == "#":
        value = -0.4  # hash comment
    else:
        value = 0.0
    return carry, value

