    (-0.006, 'I me we us'),
    (-0.022, 'you your'),
    (-0.036, 'our their'),
    (-0.042, 'each either neither'),
    (-0.049, 'even although however always'),
    (0.044, 'who whom because'),
    (0.028, 'few many most every any'),
    (-0.030, 'back later before until'),
    (0.030, 'also still already again now'),
    (-0.057, 'through without despite unlike'),
    (0.051, 'across beyond outside towards off'),
    (-0.033, 'people men man family families friend friends'),
    (0.018, 'life'),
    (-0.018, 'lives day days times'),
    (-0.025, 'generation'),
    (-0.210, 'generations lifetime'),
    (-0.056, 'personal ancient modern'),
    (0.082, 'mother daughter brother sister parent student'),
    (0.050, 'summary conclusion review'),
    (0.074, 'express convey depiction'),
    (0.044, 'time years world history'),
)
