TIME_PHRASES = {
    ('old', 'days'): -0.48,
    ('old', 'times'): -0.48,
    ('present', 'day'): -0.35,
    ('modern', 'times'): -0.28,
    ('ancient', 'times'): -0.28,
    ('long', 'time'): -0.08,
    ('short', 'time'): -0.08,
    ('one', 'day'): -0.16,
