OF_POSITIVE = set('because part some lot couple sense use kind process '
                  'importance loss removal'.split())
OF_NEGATIVE = set('number set piece point rate time day days terms snippet '
                  'capable consists consisting board'.split())
INFINITIVE_CUES = set('want wanted need needed ready important ability easy '
                      'easier opportunity chance'.split())


def east_asian(token, tail):
    root = tail[-1:]
    if token in {'輩', '辈'}:  # Generational/peer suffix.
        return -0.68 if root in '先父祖老我' and root else -0.32
    if token in PERSON_ENDINGS:
        value = -0.10 if token in {'人', '人的'} else -0.21
        if root and root in '先后後前仙贵貴谁誰亲親家':
            value = -0.72
        elif root and root in '众眾男客唐楚吴吳':
            value = -0.53
        elif root == '友':  # Friend/peer.
            value = -0.30
        elif root.isdigit() or (root and root in '十百千万萬亿億'):
            value = 0.0  # 人 as a numerical count of people.
        elif root and root in '托诉訴权權利件责責':
            value = 0.05  # Administrative/legal agent nouns.
        return value
