        return -0.33
    if token == '室':  # Royal household, guest room, or ordinary room.
        return -0.90 if root == '王' else -0.56 if root in {'皇', '客'} else -0.08
    if token == '祖':
        return -0.76 if root == '先' else -0.15
    if token == '徒':  # Teacher-disciple or pupil compounds.
        return -0.64 if root in {'师', '師', '家'} else -0.37 if root == '生' else -0.08
    if token in {'朝', '世'}:
        return -0.67 if root == '今' else -0.22 if token == '朝' else -0.12
    if token in {'门', '門', '国', '國'} and root == '家':
        return -0.64
