def english(word, before):
    value = LEXICAL.get(word, 0.0)
    if word in {'life', 'lives', 'lifetime'} and before in POSSESSIVES:
        value -= 0.19 + (0.15 if before == 'personal' else 0.0)
    if word in SOCIAL | {'home'} and before in POSSESSIVES:
        value -= 0.11 + (0.09 if before == 'my' else 0.0)
    if word in {'generation', 'generations'} and before in GENERATIONS:
        value -= 0.30 if word == 'generations' else 0.20
    if word in SOCIAL and before in AGE:
        value -= 0.25 if before == 'old' else 0.12
    if word == 'people' and before in {'other', 'common'}:
        value -= 0.20
