        if s.startswith('こと') and len(s) >= 5:
            return -0.2 if s.endswith('ます') else -0.8
        if s.startswith(('とな', 'とい', 'からの', 'ととも', 'など')) and len(s) > 2:
            return -0.6
        if s.startswith(('するため', 'させて頂', 'はあり', 'もない', 'るの')):
            return -0.85
        if 'こと' in s and not s.startswith(('こと', 'のこと')):
            return -1.2
        if s.startswith(('と思', 'と言', 'と考')):
            return -1.2
        if s.startswith(('のご', 'のお', 'もあ', 'はな', 'いただ')):
            return -0.75
        if any(x in s for x in ('ながら', 'てしま', 'れている', 'られて')):
            return -0.5
        return 0.0

    # Arabic bound prepositions and conjunctions fused to following material.
    if s.startswith(('بشكل', 'بنسبة', 'بما', 'باستخدام')):
        return -2.2
    if len(s) >= 3 and s.startswith('لل'):
        return -1.2
    if len(s) >= 3 and s.startswith(('وال', 'وأن')):
        return -0.3
    if s.lower() in {'throughout', 'surrounded', 'statewide', 'nationwide', 'worldwide'}:
        return -0.5

    # Angle-prefixed names, annotations, and camel-case operation phrases.
    name = s.lstrip('.<([{@=,>:/\\')
    if name not in {'toString', 'toBe', 'toEqual'} and re.match(
        r'(get|set|Get|Set|to|To|is|Is|has|Has|on|On|use|Use|By|Of)[A-Z]', name
    ):
        return -0.7
    if re.match(r'(show|close|update|add|New|With|load|create)[A-Z]', name):
        return -0.5
    if re.match(r'<(?:[A-Z]|string|byte|int|char|bool|object)', s):
        return -0.4
    if re.match(r'@[A-Za-z]{3,}', s):
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    return None, activation(prefix.token_strings[-1])

"""A local token-boundary spelling cue, plus a separate response after 'which'.

Unspaced continuations after h/j or sibilant-like endings tend to be negative
when they start with i/y, and positive with a/o. Short spelling pieces have
stronger responses; long tokens and common -ing are weaker. The character
groups include approximate counterparts in several scripts.

Tokens after 'which' receive a negative clause-opening response, followed
by a weaker one-token tail. The only state is the previous token and that
tail flag, both cleared when the document changes. Other tokens get zero.
This approximation leaves word-specific exceptions unresolved.
"""
import unicodedata

READS = ()

# Clause-opening function words and question selectors after 'which'.
CLAUSE_OPENERS = {
    'is': -1.96, 'are': -1.21, 'was': -1.72, 'were': -1.47,
    'can': -1.57, 'will': -1.77, 'would': -1.32, 'could': -1.32,
    'has': -1.12, 'have': -0.78, 'had': -0.94, 'does': -1.25,
    'may': -1.02, 'might': -1.10, 'should': -1.05, 'means': -1.0,
    'it': -1.79, 'i': -1.52, 'we': -1.4, 'you': -1.32,
    'he': -1.02, 'she': -0.8, 'they': -1.24, 'the': -0.81,
    'of': -2.0, 'in': -1.35, 'to': -1.24, 'also': -1.89,
    'case': -3.0, 'time': -3.3, 'point': -2.1, 'times': -2.7,
}
# Approximate h/j and sh/ch-like spellings in several scripts.
H_AND_SIBILANT_ENDINGS = 'hjšžčşżřzшщжчхχهحخشجچژہھชจ'
VOWEL_FAMILIES = {
    'a': 'aаαاะาั', 'e': 'eеэε', 'i': 'iиіιηىیيِิีı',
    'o': 'oоοω', 'u': 'uуوุู', 'y': 'yыьυ',
}
VOWEL_MAP = {letter: kind for kind, letters in VOWEL_FAMILIES.items()
             for letter in letters}


def continuation_response(token):
    # Short spelling pieces are more informative than long continuations.
    c = first_letter(token)
    n = len(token)
    if token.lower() in ('ing', 'ings'):
        return -0.55  # Common English participle endings are weaker.
    if c == 'i':
        return -1.9 * max(0.2, 1.0 - 0.22 * max(0, n - 2))
    if c == 'y':
        return -1.3 if n <= 3 else -0.3
    if c in 'ao':
        peak = 1.1 if c == 'a' else 0.7
        if n == 1:
            return 0.55
        return peak * 0.8 ** min(5, n - 2)
    if c == 'e':
        return -0.2 if n <= 2 else 0.0
    if c == 'u':
        return 0.0 if n == 1 else 0.23 if n == 2 else 0.35
    return 0.24 if n <= 2 else 0.13


def first_letter(token):
    c = unicodedata.normalize('NFD', token[0].lower())[0]
    return VOWEL_MAP.get(c, c)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    after_two = bool(carry and carry[0] == doc and carry[2])
    word = previous.strip()
    value = 0.0
    if word.lower() == 'which':
        value = CLAUSE_OPENERS.get(token.strip().lower(), -0.55)
        if word[0].isupper():
            value *= 1.2
    elif previous and previous[-1].lower() in H_AND_SIBILANT_ENDINGS:
        if (token and not token[0].isspace()
                and (token[0].isalpha() or token[0] in VOWEL_MAP)):
            value = continuation_response(token)
            ending = previous.lower()[-2:]
            if ending in ('th', 'ph', 'wh'):
                value = 0.66 * value - 0.06
            elif ending in ('ah', 'eh', 'ih', 'oh', 'uh'):
                value = 1.07 * value - 0.33
            elif previous[-1].lower() == 'j':
                value = 0.85 * value - 0.13
            elif previous[-1].lower() == 'z':
                value *= 0.25
            elif previous[-1].lower() == 'щ':
                value *= 0.4
            elif previous[-1].lower() != 'h':
                value = 0.72 * value + 0.03
            elif ending not in ('ch', 'sh'):
                value -= 0.16

    if after_two and value == 0.0:
        value = {'be': -0.63, 'been': -0.34, 'also': -0.38,
                 'to': -0.2, "'t": -0.48, '’t': -0.48}.get(
                     token.strip().lower(), -0.1)
    return (doc, token, word.lower() == 'which'), float(value)

programs.haiku:
"""Layer-0 MLP output unit 3262 (down_proj), as a readable rule.

What it does: this unit is mostly silent. Its clearest behaviour is on the word right after a
relative or question "which": the next token gets a negative activation, strongest before
"of" and before auxiliaries/verbs ("which is", "which can", "which will"), weaker before
determiners and punctuation ("which the", "which a", "which,"). Everywhere else it predicts 0.
Positions where the previous token is not "which" are predicted as 0, and a new document
resets the rule.
"""
READS = ()

WHICH = {" which", " Which", "which", "Which"}
OF = {" of"}
AUX_OR_VERB = {
    " is", " are", " was", " were", " be", " can", " will", " would", " could", " should",
    " may", " might", " must", " has", " have", " had", " does", " do", " did", " means",
    " includes", " gives", " makes", " requires", " allows", " provides", " contains",
    " leads", " causes", " results",
}
DETERMINER_OR_PUNCT = {" the", " a", " an", " one", " this", " that", " these", " those", ",", "."}


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    if prefix.token_strings[-2] not in WHICH:
        return None, 0.0
    word = prefix.token_strings[-1]
    if word in OF:
        return None, -2.4
    if word in AUX_OR_VERB:
        return None, -1.6
    if word in DETERMINER_OR_PUNCT:
        return None, -0.7
    return None, -0.6

programs.sol:
"""Approximate lexical continuation and return cues.

The largest negative responses are to words like 'also', 'still', and
'further', their translations, and return forms. Chinese 还/還 is strongest;
compounds expressing 'or', 'not yet', or repayment are weaker. This is a
lexical approximation, not a sentence-level interpretation of meaning.
Capitalization and lack of a leading space weaken English 'also'/'still'.
Selected preceding modal/linking verbs strengthen these cues; conjunctions
and punctuation weaken them. The end-of-text marker gives a positive
response. Unrecognized tokens get zero, ignoring smaller lexical offsets.
"""
READS = ()

# Translations of also, still, yet, and furthermore, with different strengths.
CONTINUATION = {
    'auch': -1.1, 'noch': -1.8, 'sondern': -0.75, 'samt': -0.5,
    'außerdem': -1.3, 'dann': -0.45, 'weiter': -0.5,
    'aussi': -1.0, 'encore': -2.1, 'également': -1.2, 'alors': -0.5,
    'anche': -1.1, 'ancora': -1.5,
    'también': -1.9, 'además': -1.6, 'aún': -1.6, 'todavía': -2.1,
    'também': -1.3, 'ainda': -2.9,
    'ещё': -2.7, 'еще': -2.2, 'также': -1.4, 'кроме': -0.6,
    'også': -1.5, 'också': -1.1, 'även': -2.5,
    'także': -1.9, 'również': -1.25, 'jeszcze': -1.65,
    'ook': -0.7, 'nog': -0.6,
    'cũng': -0.65, 'còn': -3.8, 'chưa': -1.2, 'vẫn': -1.2,
    'juga': -2.1, 'masih': -2.0, 'ayrıca': -1.3,
}
JAPANESE = {
    'まだ': -3.0, 'まだまだ': -2.8, 'さらに': -2.5,
    'また': -0.9, 'にも': -1.0, 'もう': -1.1, 'も': -0.4,
    'しかも': -1.8, 'あと': -1.6, 'ても': -0.7, 'もある': -0.8,
}
SIMPLIFY = str.maketrans('還會將沒償', '还会将没偿')


def chinese(word):
    """Continuation particles, keeping non-adverbial senses separate."""
    w = word.translate(SIMPLIFY)
    if '还' in w:
        scale = 0.92 if '還' in word else 1.0
        if w == '还':
            value = -8.1
        elif any(x in w for x in ('还原', '返还', '退还', '归还')):
            value = -0.95  # restore, rather than still
        elif '偿还' in w or '还款' in w:
            value = -2.7  # repay
        elif w.startswith('还是'):
            value = -3.9 if len(w) == 2 else -2.9  # still / or
        elif w.startswith('还不是'):
            value = -5.1
        elif w.startswith(('还没', '还未', '还不如', '还记得', '还以为')):
            value = -3.2  # weaker fixed expressions
        elif w.startswith('还真'):
            value = -2.9
        elif w.startswith('还不错'):
            value = -3.8
        elif w in {'还好', '还挺', '还得'}:
            value = -4.7
        elif w in {'还要', '还不'}:
            value = -7.4
        elif w.startswith('还有') and len(w) > 2:
            value = -4.2  # also has + an attached quantifier
        elif w.startswith('还'):
            value = -6.3 / (1.0 + 0.2 * max(0, len(w) - 3))
        elif w.endswith('还'):
            value = -7.0 if w[:-1] in {'我', '你', '他', '她'} else -5.0
        else:
            value = -3.0
        return value * scale
    if w == '而且':
        return -1.55
    if w in {'且', '亦', '此外', '并且'}:
        return -0.85
    if w in {'尚', '尚未', '依然', '依旧'}:
        return -1.5
    if w.startswith('仍'):
        return -2.2 if w in {'仍', '仍在', '仍有'} else -1.4
    if '也' in w and not any(x in w for x in ('也许', '也就是')):
        return -0.65 if '也是' in w else -1.0
    if w.startswith('又'):
        return -1.1
    if w in {'更', '更是', '进一步'}:
        return -1.0
    if w.startswith('更'):
        return -0.4
    if w == '再':
        return -0.65
    return None


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._@()-')
    if '\ufffd' in token:
        # A byte fragment may finish a Chinese continuation character.
        completed = prefix.text_prefixes[-1][-1:]
        if completed in '还還也更仍又':
            word = completed
    lower = word.lower()
    if token == '<|endoftext|>':
        value = 0.85
    elif lower in {'also', 'still'}:
        strong = token.startswith(' ') and word.islower()
        value = (-2.3 if lower == 'also' else -2.1) if strong else -1.3
        if (strong and prefix.position > 0
                and prefix.document_ids[-2] == prefix.document_ids[-1]):
            previous = prefix.token_strings[-2].strip().lower()
            if previous in {'may', 'might'}:
                value -= 0.65
            elif previous in {'can', 'could', 'will', 'would', 'should'}:
                value -= 0.25
            elif previous in {'is', 'was'}:
                value -= 0.1
            elif previous in {'and', 'while', 'both'}:
                value += 0.45
            elif previous == 'but':
                value += 0.25
            elif previous and not any(c.isalnum() for c in previous):
                value += 0.3
    elif lower in {'then', 'thenreturn'}:
        if lower == 'thenreturn':
            value = -1.3  # a return-value chaining method
        else:
            value = -0.87 if word.islower() else -0.78
    elif lower in {'return', 'returns', 'returned', 'returning'}:
        value = {'return': -1.23, 'returns': -0.8,
                 'returned': -0.86, 'returning': -1.0}[lower]
        if not word.islower():
            value *= 0.8
    elif lower in {'further', 'moreover', 'furthermore', 'additionally'}:
        value = -0.7 if lower == 'additionally' else -1.25
    elif lower in CONTINUATION and token[:1].isspace():
        value = CONTINUATION[lower]
        if word[:1].isupper():
            value *= 0.7
    elif word in JAPANESE:
        value = JAPANESE[word]
    else:
        value = chinese(word)
        if value is None:
            value = 0.0
    return None, float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 3263: an "also / still / then" detector.

The component writes a negative signal on words that add one more thing to a clause:
English "also" and "still" (strongest), other-language equivalents ("encore", "auch",
"también", "также"), the Chinese particle 还 / 還 ("still, also, even, in addition"),
sequencing and adding adverbs ("then", "further", "furthermore", "moreover"), and the
word "return" in code. It is mildly positive at the end-of-text token. Everywhere else
it is near zero. Its size tracks how strong the word is, as set out in the constants.
"""

READS = ()

# English "also" and "still": the clearest cases.
ALSO_STILL_EN = {"also", "still"}
ALSO_STILL = -2.2
# Other-language words for "also / still / too / yet".
ALSO_OTHER = {
    "encore", "noch", "también", "tambien", "auch", "anche", "aussi", "ancora", "ainda",
    "ещё", "еще", "также", "także", "também", "även", "också", "també", "również",
    "également", "ebenfalls", "jeszcze", "też", "cũng", "còn", "まだ", "さらに", "また",
}
ALSO_OTHER_VALUE = -1.4
# Chinese: 还 / 還 ("still, also, even") is the strongest response; 还是 ("still/or") weaker.
HUAN = -6.5
HUANSHI = -3.7
# Chinese additive adverbs: 也 又 更 仍 尚 亦 而且 此外 再.
ZH_ADD = {"也", "又", "更", "仍", "尚", "亦", "而且", "此外", "再", "仍然", "也是", "也会"}
ZH_ADD_VALUE = -1.2
# Sequencing and adding adverbs: then, further, moreover, furthermore, additionally.
THEN_LIKE = {"then", "further", "furthermore", "moreover", "additionally"}
THEN_VALUE = -1.0
# The word "return" and its forms (mostly in code).
RETURN = {"return", "returns", "returned", "returning"}
RETURN_VALUE = -1.1
END_OF_TEXT = 0.85


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if raw == "<|endoftext|>":
        value = END_OF_TEXT
    elif "还是" in raw or "還是" in raw:
        value = HUANSHI
    elif "还" in raw or "還" in raw:
        value = HUAN
    elif word in ALSO_STILL_EN:
        value = ALSO_STILL
    elif word in ALSO_OTHER or raw in ALSO_OTHER:
        value = ALSO_OTHER_VALUE
    elif raw in ZH_ADD:
        value = ZH_ADD_VALUE
    elif word in THEN_LIKE:
        value = THEN_VALUE
    elif word in RETURN:
        value = RETURN_VALUE
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Approximate continuation/addition words and the end-of-document marker.

The largest repeatable responses are negative on words like “also,” “still,”
and “then,” including equivalents in several languages, and on “return” forms;
the document separator is positive. Context effects and other words are left
out.
"""

READS = ()

ADDITIONAL = {
    "further", "Further", "furthermore", "Furthermore",
    "additionally", "Additionally", "additional", "Additional",
    "moreover", "auch", "Auch", "anche", "Anche", "aussi",
    "также", "也", "又", "も", "にも", "また", "更", "samt",
}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word == "<|endoftext|>":
        return None, 0.85
    if word == "also":
        return None, -2.3
    if word == "Also":
        return None, -1.3
    if word in {"还", "還"}:
        return None, -8.0
    if word == "还是":
        return None, -3.8
    if word in {
        "encore", "Encore", "still", "Still", "仍", "还", "還", "まだ",
    }:
        return None, -2.1
    if word in {"noch", "Noch"}:
        return None, -1.65
    if word in ADDITIONAL:
        return None, -1.1
    if word in {"then", "Then"}:
        return None, -0.85
    if word in {
        "return", "Return",
    }:
        return None, -1.25
    if word in {
        "returns", "Returns", "returned", "Returned", "returning", "Returning",
    }:
        return None, -0.9
    return None, 0.0
